window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ZEC"]={"book":"ZEC","editions":{"hbo-source":[[1,1,"בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שְּׁמִינִ֔י בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֑וֶשׁ הָיָ֣ה דְבַר־יְהוָ֗ה אֶל־זְכַרְיָה֙ בֶּן־בֶּ֣רֶכְיָ֔ה בֶּן־עִדּ֥וֹ הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bȧ⁠ẖò֨deş̌֙ ha⁠şĕ̇̌miyni֔y bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֑weş̌ háyá֣h dĕbar-yĕhwá֗h ʼel-zĕkarĕyáh֙ bėn-bė֣rekĕyá֔h bėn-ʻiḋ֥wò ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[1,2,"קָצַ֧ף יְהוָ֛ה עַל־אֲבֽוֹתֵי⁠כֶ֖ם קָֽצֶף׃","qáẕa֧p yĕhwá֛h ʻal-ʼàbֽwòţéy⁠ke֖m qáֽẕep׃"],[1,3,"וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֗ם כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת שׁ֣וּבוּ אֵלַ֔⁠י נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת וְ⁠אָשׁ֣וּב אֲלֵי⁠כֶ֔ם אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֗m kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ş֣̌ẇbẇ ʼéla֔⁠y nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠ʼáş֣̌ẇb ʼàléy⁠ke֔m ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[1,4,"אַל־תִּהְי֣וּ כַ⁠אֲבֹֽתֵי⁠כֶ֡ם אֲשֶׁ֣ר קָרְאֽוּ־אֲלֵי⁠הֶם֩ הַ⁠נְּבִיאִ֨ים הָ⁠רִֽאשֹׁנִ֜ים לֵ⁠אמֹ֗ר כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת שׁ֤וּבוּ נָא֙ מִ⁠דַּרְכֵי⁠כֶ֣ם הָ⁠רָעִ֔ים ו⁠מעלילי⁠כם הָֽ⁠רָעִ֑ים וְ⁠לֹ֥א שָׁמְע֛וּ וְ⁠לֹֽא־הִקְשִׁ֥יבוּ אֵלַ֖⁠י נְאֻם־יְהוָֽה׃","ʼal-ţi̇hĕy֣ẇ ka⁠ʼàbòֽţéy⁠ke֡m ʼàşě֣r qárĕʼֽẇ-ʼàléy⁠hem֩ ha⁠nĕ̇biyʼi֨ym há⁠riֽʼşò̌ni֜ym lé⁠ʼmò֗r kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ş֤̌ẇbẇ náʼ֙ mi⁠dȧrĕkéy⁠ke֣m há⁠ráʻi֔ym w⁠mʻlyly⁠km háֽ⁠ráʻi֑ym wĕ⁠lò֥ʼ şá̌mĕʻ֛ẇ wĕ⁠lòֽʼ-hiqĕşǐ֥ybẇ ʼéla֖⁠y nĕʼum-yĕhwáֽh׃"],[1,5,"אֲבֽוֹתֵי⁠כֶ֖ם אַיֵּה־הֵ֑ם וְ⁠הַ֨⁠נְּבִאִ֔ים הַ⁠לְ⁠עוֹלָ֖ם יִֽחְיֽוּ׃","ʼàbֽwòţéy⁠ke֖m ʼayé̇h-hé֑m wĕ⁠ha֨⁠nĕ̇biʼi֔ym ha⁠lĕ⁠ʻwòlá֖m yiֽẖĕyֽẇ׃"],[1,6,"אַ֣ךְ ׀ דְּבָרַ֣⁠י וְ⁠חֻקַּ֗⁠י אֲשֶׁ֤ר צִוִּ֨יתִי֙ אֶת־עֲבָדַ֣⁠י הַ⁠נְּבִיאִ֔ים הֲ⁠ל֥וֹא הִשִּׂ֖יגוּ אֲבֹתֵי⁠כֶ֑ם וַ⁠יָּשׁ֣וּבוּ וַ⁠יֹּאמְר֗וּ כַּ⁠אֲשֶׁ֨ר זָמַ֜ם יְהוָ֤ה צְבָאוֹת֙ לַ⁠עֲשׂ֣וֹת לָ֔⁠נוּ כִּ⁠דְרָכֵ֨י⁠נוּ֙ וּ⁠כְ⁠מַ֣עֲלָלֵ֔י⁠נוּ כֵּ֖ן עָשָׂ֥ה אִתָּֽ⁠נוּ׃ס","ʼa֣kĕ ׀ dĕ̇bára֣⁠y wĕ⁠ẖuqȧ֗⁠y ʼàşě֤r ẕiwi̇֨yţiy֙ ʼeţ-ʻàbáda֣⁠y ha⁠nĕ̇biyʼi֔ym hà⁠l֥wòʼ hişi֖̇̂ygẇ ʼàbòţéy⁠ke֑m wa⁠yá̇ş֣̌ẇbẇ wa⁠yò̇ʼmĕr֗ẇ kȧ⁠ʼàşě֨r záma֜m yĕhwá֤h ẕĕbáʼwòţ֙ la⁠ʻàş֣̂wòţ lá֔⁠nẇ ki̇⁠dĕráké֨y⁠nẇ֙ ẇ⁠kĕ⁠ma֣ʻàlálé֔y⁠nẇ ké֖̇n ʻáşá֥̂h ʼiţáֽ̇⁠nẇ׃s"],[1,7,"בְּ⁠יוֹם֩ עֶשְׂרִ֨ים וְ⁠אַרְבָּעָ֜ה לְ⁠עַשְׁתֵּֽי־עָשָׂ֥ר חֹ֨דֶשׁ֙ הוּא־חֹ֣דֶשׁ שְׁבָ֔ט בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֑וֶשׁ הָיָ֣ה דְבַר־יְהוָ֗ה אֶל־זְכַרְיָה֙ בֶּן־בֶּ֣רֶכְיָ֔הוּ בֶּן־עִדּ֥וֹא הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bĕ̇⁠ywòm֩ ʻeşĕ̂ri֨ym wĕ⁠ʼarĕbá̇ʻá֜h lĕ⁠ʻaşĕ̌ţéֽ̇y-ʻáşá֥̂r ẖò֨deş̌֙ hẇʼ-ẖò֣deş̌ şĕ̌bá֔t bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֑weş̌ háyá֣h dĕbar-yĕhwá֗h ʼel-zĕkarĕyáh֙ bėn-bė֣rekĕyá֔hẇ bėn-ʻiḋ֥wòʼ ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[1,8,"רָאִ֣יתִי ׀ הַ⁠לַּ֗יְלָה וְ⁠הִנֵּה־אִישׁ֙ רֹכֵב֙ עַל־ס֣וּס אָדֹ֔ם וְ⁠ה֣וּא עֹמֵ֔ד בֵּ֥ין הַ⁠הֲדַסִּ֖ים אֲשֶׁ֣ר בַּ⁠מְּצֻלָ֑ה וְ⁠אַחֲרָי⁠ו֙ סוּסִ֣ים אֲדֻמִּ֔ים שְׂרֻקִּ֖ים וּ⁠לְבָנִֽים׃","ráʼi֣yţiy ׀ ha⁠lȧ֗yĕláh wĕ⁠hiné̇h-ʼiyş̌֙ ròkéb֙ ʻal-s֣ẇs ʼádò֔m wĕ⁠h֣ẇʼ ʻòmé֔d bé֥̇yn ha⁠hàdasi֖̇ym ʼàşě֣r bȧ⁠mĕ̇ẕulá֑h wĕ⁠ʼaẖàráy⁠w֙ sẇsi֣ym ʼàdumi̇֔ym şĕ̂ruqi֖̇ym ẇ⁠lĕbániֽym׃"],[1,9,"וָ⁠אֹמַ֖ר מָה־אֵ֣לֶּה אֲדֹנִ֑⁠י וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הַ⁠מַּלְאָךְ֙ הַ⁠דֹּבֵ֣ר בִּ֔⁠י אֲנִ֥י אַרְאֶ֖⁠ךָּ מָה־הֵ֥מָּה אֵֽלֶּה׃","wá⁠ʼòma֖r máh-ʼé֣lėh ʼàdòni֑⁠y wa⁠yò֣̇ʼmer ʼéla֗⁠y ha⁠mȧlĕʼákĕ֙ ha⁠dò̇bé֣r bi̇֔⁠y ʼàni֥y ʼarĕʼe֖⁠ká̇ máh-hé֥má̇h ʼéֽlėh׃"],[1,10,"וַ⁠יַּ֗עַן הָ⁠אִ֛ישׁ הָ⁠עֹמֵ֥ד בֵּין־הַ⁠הַדַסִּ֖ים וַ⁠יֹּאמַ֑ר אֵ֚לֶּה אֲשֶׁ֣ר שָׁלַ֣ח יְהוָ֔ה לְ⁠הִתְהַלֵּ֖ךְ בָּ⁠אָֽרֶץ׃","wa⁠yȧ֗ʻan há⁠ʼi֛yş̌ há⁠ʻòmé֥d bé̇yn-ha⁠hadasi֖̇ym wa⁠yò̇ʼma֑r ʼé֚lėh ʼàşě֣r şá̌la֣ẖ yĕhwá֔h lĕ⁠hiţĕhalé֖̇kĕ bá̇⁠ʼáֽreẕ׃"],[1,11,"וַֽ⁠יַּעֲנ֞וּ אֶת־מַלְאַ֣ךְ יְהוָ֗ה הָֽ⁠עֹמֵד֙ בֵּ֣ין הַ⁠הֲדַסִּ֔ים וַ⁠יֹּאמְר֖וּ הִתְהַלַּ֣כְנוּ בָ⁠אָ֑רֶץ וְ⁠הִנֵּ֥ה כָל־הָ⁠אָ֖רֶץ יֹשֶׁ֥בֶת וְ⁠שֹׁקָֽטֶת׃","waֽ⁠yȧʻàn֞ẇ ʼeţ-malĕʼa֣kĕ yĕhwá֗h háֽ⁠ʻòméd֙ bé֣̇yn ha⁠hàdasi̇֔ym wa⁠yò̇ʼmĕr֖ẇ hiţĕhalȧ֣kĕnẇ bá⁠ʼá֑reẕ wĕ⁠hiné֥̇h kál-há⁠ʼá֖reẕ yòşě֥beţ wĕ⁠şò̌qáֽteţ׃"],[1,12,"וַ⁠יַּ֣עַן מַלְאַךְ־יְהוָה֮ וַ⁠יֹּאמַר֒ יְהוָ֣ה צְבָא֔וֹת עַד־מָתַ֗י אַתָּה֙ לֹֽא־תְרַחֵ֣ם אֶת־יְרוּשָׁלִַ֔ם וְ⁠אֵ֖ת עָרֵ֣י יְהוּדָ֑ה אֲשֶׁ֣ר זָעַ֔מְתָּה זֶ֖ה שִׁבְעִ֥ים שָׁנָֽה׃","wa⁠yȧ֣ʻan malĕʼakĕ-yĕhwáh֮ wa⁠yò̇ʼmar֒ yĕhwá֣h ẕĕbáʼ֔wòţ ʻad-máţa֗y ʼaţá̇h֙ lòֽʼ-ţĕraẖé֣m ʼeţ-yĕrẇşá̌lia֔m wĕ⁠ʼé֖ţ ʻáré֣y yĕhẇdá֑h ʼàşě֣r záʻa֔mĕţá̇h ze֖h şǐbĕʻi֥ym şá̌náֽh׃"],[1,13,"וַ⁠יַּ֣עַן יְהוָ֗ה אֶת־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י דְּבָרִ֣ים טוֹבִ֑ים דְּבָרִ֖ים נִחֻמִֽים׃","wa⁠yȧ֣ʻan yĕhwá֗h ʼeţ-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y dĕ̇bári֣ym twòbi֑ym dĕ̇bári֖ym niẖumiֽym׃"],[1,14,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הַ⁠מַּלְאָךְ֙ הַ⁠דֹּבֵ֣ר בִּ֔⁠י קְרָ֣א לֵ⁠אמֹ֔ר כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת קִנֵּ֧אתִי לִ⁠ירוּשָׁלִַ֛ם וּ⁠לְ⁠צִיּ֖וֹן קִנְאָ֥ה גְדוֹלָֽה׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y ha⁠mȧlĕʼákĕ֙ ha⁠dò̇bé֣r bi̇֔⁠y qĕrá֣ʼ lé⁠ʼmò֔r kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ qiné֧̇ʼţiy li⁠yrẇşá̌lia֛m ẇ⁠lĕ⁠ẕiẏ֖wòn qinĕʼá֥h gĕdwòláֽh׃"],[1,15,"וְ⁠קֶ֤צֶף גָּדוֹל֙ אֲנִ֣י קֹצֵ֔ף עַל־הַ⁠גּוֹיִ֖ם הַ⁠שַּֽׁאֲנַנִּ֑ים אֲשֶׁ֤ר אֲנִי֙ קָצַ֣פְתִּי מְּעָ֔ט וְ⁠הֵ֖מָּה עָזְר֥וּ לְ⁠רָעָֽה׃","wĕ⁠qe֤ẕep gá̇dwòl֙ ʼàni֣y qòẕé֔p ʻal-ha⁠ġwòyi֖m ha⁠şȧֽ̌ʼànani֑̇ym ʼàşě֤r ʼàniy֙ qáẕa֣pĕţi̇y mĕ̇ʻá֔t wĕ⁠hé֖má̇h ʻázĕr֥ẇ lĕ⁠ráʻáֽh׃"],[1,16,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה שַׁ֤בְתִּי לִ⁠ירוּשָׁלִַ֨ם֙ בְּֽ⁠רַחֲמִ֔ים בֵּיתִ⁠י֙ יִבָּ֣נֶה בָּ֔⁠הּ נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת ו⁠קוה יִנָּטֶ֖ה עַל־יְרוּשָׁלִָֽם׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h şǎ֤bĕţi̇y li⁠yrẇşá̌lia֨m֙ bĕֽ̇⁠raẖàmi֔ym bé̇yţi⁠y֙ yibá֣̇neh bá̇֔⁠ḣ nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ w⁠qwh yiná̇te֖h ʻal-yĕrẇşá̌liáֽm׃"],[1,17,"ע֣וֹד ׀ קְרָ֣א לֵ⁠אמֹ֗ר כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת ע֛וֹד תְּפוּצֶ֥ינָה עָרַ֖⁠י מִ⁠טּ֑וֹב וְ⁠נִחַ֨ם יְהוָ֥ה עוֹד֙ אֶת־צִיּ֔וֹן וּ⁠בָחַ֥ר ע֖וֹד בִּ⁠ירוּשָׁלִָֽם׃ס","ʻ֣wòd ׀ qĕrá֣ʼ lé⁠ʼmò֗r kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻ֛wòd ţĕ̇pẇẕe֥ynáh ʻára֖⁠y mi⁠ṫ֑wòb wĕ⁠niẖa֨m yĕhwá֥h ʻwòd֙ ʼeţ-ẕiẏ֔wòn ẇ⁠báẖa֥r ʻ֖wòd bi̇⁠yrẇşá̌liáֽm׃s"],[1,18,"וָ⁠אֶשָּׂ֥א אֶת־עֵינַ֖⁠י וָ⁠אֵ֑רֶא וְ⁠הִנֵּ֖ה אַרְבַּ֥ע קְרָנֽוֹת׃","wá⁠ʼeşá֥̇̂ʼ ʼeţ-ʻéyna֖⁠y wá⁠ʼé֑reʼ wĕ⁠hiné֖̇h ʼarĕbȧ֥ʻ qĕránֽwòţ׃"],[1,19,"וָ⁠אֹמַ֗ר אֶל־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י מָה־אֵ֑לֶּה וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י אֵ֤לֶּה הַ⁠קְּרָנוֹת֙ אֲשֶׁ֣ר זֵר֣וּ אֶת־יְהוּדָ֔ה אֶת־יִשְׂרָאֵ֖ל וִ⁠ירוּשָׁלָֽם׃ס","wá⁠ʼòma֗r ʼel-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y máh-ʼé֑lėh wa⁠yò֣̇ʼmer ʼéla֔⁠y ʼé֤lėh ha⁠qĕ̇ránwòţ֙ ʼàşě֣r zér֣ẇ ʼeţ-yĕhẇdá֔h ʼeţ-yişĕ̂ráʼé֖l wi⁠yrẇşá̌láֽm׃s"],[1,20,"וַ⁠יַּרְאֵ֣⁠נִי יְהוָ֔ה אַרְבָּעָ֖ה חָרָשִֽׁים׃","wa⁠yȧrĕʼé֣⁠niy yĕhwá֔h ʼarĕbá̇ʻá֖h ẖáráşǐֽym׃"],[1,21,"וָ⁠אֹמַ֕ר מָ֛ה אֵ֥לֶּה בָאִ֖ים לַֽ⁠עֲשׂ֑וֹת וַ⁠יֹּ֣אמֶר לֵ⁠אמֹ֗ר אֵ֣לֶּה הַ⁠קְּרָנ֞וֹת אֲשֶׁר־זֵ֣רוּ אֶת־יְהוּדָ֗ה כְּ⁠פִי־אִישׁ֙ לֹא־נָשָׂ֣א רֹאשׁ֔⁠וֹ וַ⁠יָּבֹ֤אוּ אֵ֨לֶּה֙ לְ⁠הַחֲרִ֣יד אֹתָ֔⁠ם לְ⁠יַדּ֞וֹת אֶת־קַרְנ֣וֹת הַ⁠גּוֹיִ֗ם הַ⁠נֹּשְׂאִ֥ים קֶ֛רֶן אֶל־אֶ֥רֶץ יְהוּדָ֖ה לְ⁠זָרוֹתָֽ⁠הּ׃ס","wá⁠ʼòma֕r má֛h ʼé֥lėh báʼi֖ym laֽ⁠ʻàş֑̂wòţ wa⁠yò֣̇ʼmer lé⁠ʼmò֗r ʼé֣lėh ha⁠qĕ̇rán֞wòţ ʼàşěr-zé֣rẇ ʼeţ-yĕhẇdá֗h kĕ̇⁠piy-ʼiyş̌֙ lòʼ-náşá֣̂ʼ ròʼş̌֔⁠wò wa⁠yá̇bò֤ʼẇ ʼé֨lėh֙ lĕ⁠haẖàri֣yd ʼòţá֔⁠m lĕ⁠yaḋ֞wòţ ʼeţ-qarĕn֣wòţ ha⁠ġwòyi֗m ha⁠nò̇şĕ̂ʼi֥ym qe֛ren ʼel-ʼe֥reẕ yĕhẇdá֖h lĕ⁠zárwòţáֽ⁠ḣ׃s"],[2,1,"וָ⁠אֶשָּׂ֥א עֵינַ֛⁠י וָ⁠אֵ֖רֶא וְ⁠הִנֵּה־אִ֑ישׁ וּ⁠בְ⁠יָד֖⁠וֹ חֶ֥בֶל מִדָּֽה׃","wá⁠ʼeşá֥̇̂ʼ ʻéyna֛⁠y wá⁠ʼé֖reʼ wĕ⁠hiné̇h-ʼi֑yş̌ ẇ⁠bĕ⁠yád֖⁠wò ẖe֥bel midáֽ̇h׃"],[2,2,"וָ⁠אֹמַ֕ר אָ֖נָה אַתָּ֣ה הֹלֵ֑ךְ וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י לָ⁠מֹד֙ אֶת־יְר֣וּשָׁלִַ֔ם לִ⁠רְא֥וֹת כַּ⁠מָּֽה־רָחְבָּ֖⁠הּ וְ⁠כַ⁠מָּ֥ה אָרְכָּֽ⁠הּ׃","wá⁠ʼòma֕r ʼá֖náh ʼaţá֣̇h hòlé֑kĕ wa⁠yò֣̇ʼmer ʼéla֗⁠y lá⁠mòd֙ ʼeţ-yĕr֣ẇşá̌lia֔m li⁠rĕʼ֥wòţ kȧ⁠máֽ̇h-ráẖĕbá֖̇⁠ḣ wĕ⁠ka⁠má֥̇h ʼárĕkáֽ̇⁠ḣ׃"],[2,3,"וְ⁠הִנֵּ֗ה הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י יֹצֵ֑א וּ⁠מַלְאָ֣ךְ אַחֵ֔ר יֹצֵ֖א לִ⁠קְרָאתֽ⁠וֹ׃","wĕ⁠hiné̇֗h ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y yòẕé֑ʼ ẇ⁠malĕʼá֣kĕ ʼaẖé֔r yòẕé֖ʼ li⁠qĕráʼţֽ⁠wò׃"],[2,4,"וַ⁠יֹּ֣אמֶר אֵלָ֔⁠ו רֻ֗ץ דַּבֵּ֛ר אֶל־הַ⁠נַּ֥עַר הַלָּ֖ז לֵ⁠אמֹ֑ר פְּרָזוֹת֙ תֵּשֵׁ֣ב יְרוּשָׁלִַ֔ם מֵ⁠רֹ֥ב אָדָ֛ם וּ⁠בְהֵמָ֖ה בְּ⁠תוֹכָֽ⁠הּ׃","wa⁠yò֣̇ʼmer ʼélá֔⁠w ru֗ẕ dȧbé֛̇r ʼel-ha⁠nȧ֥ʻar halá֖̇z lé⁠ʼmò֑r pĕ̇rázwòţ֙ ţé̇şé֣̌b yĕrẇşá̌lia֔m mé⁠rò֥b ʼádá֛m ẇ⁠bĕhémá֖h bĕ̇⁠ţwòkáֽ⁠ḣ׃"],[2,5,"וַ⁠אֲנִ֤י אֶֽהְיֶה־לָּ⁠הּ֙ נְאֻם־יְהוָ֔ה ח֥וֹמַת אֵ֖שׁ סָבִ֑יב וּ⁠לְ⁠כָב֖וֹד אֶֽהְיֶ֥ה בְ⁠תוֹכָֽ⁠הּ׃פ","wa⁠ʼàni֤y ʼeֽhĕyeh-lá̇⁠ḣ֙ nĕʼum-yĕhwá֔h ẖ֥wòmaţ ʼé֖ş̌ sábi֑yb ẇ⁠lĕ⁠káb֖wòd ʼeֽhĕye֥h bĕ⁠ţwòkáֽ⁠ḣ׃p"],[2,6,"ה֣וֹי ה֗וֹי וְ⁠נֻ֛סוּ מֵ⁠אֶ֥רֶץ צָפ֖וֹן נְאֻם־יְהוָ֑ה כִּ֠י כְּ⁠אַרְבַּ֞ע רוּח֧וֹת הַ⁠שָּׁמַ֛יִם פֵּרַ֥שְׂתִּי אֶתְ⁠כֶ֖ם נְאֻם־יְהוָֽה׃","h֣wòy h֗wòy wĕ⁠nu֛sẇ mé⁠ʼe֥reẕ ẕáp֖wòn nĕʼum-yĕhwá֑h ki̇֠y kĕ̇⁠ʼarĕbȧ֞ʻ rẇẖ֧wòţ ha⁠şá̇̌ma֛yim pé̇ra֥şĕ̂ţi̇y ʼeţĕ⁠ke֖m nĕʼum-yĕhwáֽh׃"],[2,7,"ה֥וֹי צִיּ֖וֹן הִמָּלְטִ֑י יוֹשֶׁ֖בֶת בַּת־בָּבֶֽל׃ס","h֥wòy ẕiẏ֖wòn himá̇lĕti֑y ywòşě֖beţ bȧţ-bá̇beֽl׃s"],[2,8,"כִּ֣י כֹ֣ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ אַחַ֣ר כָּב֔וֹד שְׁלָחַ֕⁠נִי אֶל־הַ⁠גּוֹיִ֖ם הַ⁠שֹּׁלְלִ֣ים אֶתְ⁠כֶ֑ם כִּ֚י הַ⁠נֹּגֵ֣עַ בָּ⁠כֶ֔ם נֹגֵ֖עַ בְּ⁠בָבַ֥ת עֵינֽ⁠וֹ׃","ki֣̇y kò֣h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ ʼaẖa֣r ká̇b֔wòd şĕ̌láẖa֕⁠niy ʼel-ha⁠ġwòyi֖m ha⁠şò̇̌lĕli֣ym ʼeţĕ⁠ke֑m ki֚̇y ha⁠nò̇gé֣ʻa bá̇⁠ke֔m nògé֖ʻa bĕ̇⁠bába֥ţ ʻéynֽ⁠wò׃"],[2,9,"כִּ֠י הִנְ⁠נִ֨י מֵנִ֤יף אֶת־יָדִ⁠י֙ עֲלֵי⁠הֶ֔ם וְ⁠הָי֥וּ שָׁלָ֖ל לְ⁠עַבְדֵי⁠הֶ֑ם וִֽ⁠ידַעְתֶּ֕ם כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחָֽ⁠נִי׃ס","ki̇֠y hinĕ⁠ni֨y méni֤yp ʼeţ-yádi⁠y֙ ʻàléy⁠he֔m wĕ⁠háy֥ẇ şá̌lá֖l lĕ⁠ʻabĕdéy⁠he֑m wiֽ⁠ydaʻĕţė֕m kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖáֽ⁠niy׃s"],[2,10,"רָנִּ֥י וְ⁠שִׂמְחִ֖י בַּת־צִיּ֑וֹן כִּ֧י הִנְ⁠נִי־בָ֛א וְ⁠שָׁכַנְתִּ֥י בְ⁠תוֹכֵ֖⁠ךְ נְאֻם־יְהוָֽה׃","ráni֥̇y wĕ⁠şîmĕẖi֖y bȧţ-ẕiẏ֑wòn ki֧̇y hinĕ⁠niy-bá֛ʼ wĕ⁠şá̌kanĕţi֥̇y bĕ⁠ţwòké֖⁠kĕ nĕʼum-yĕhwáֽh׃"],[2,11,"וְ⁠נִלְווּ֩ גוֹיִ֨ם רַבִּ֤ים אֶל־יְהוָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠הָ֥יוּ לִ֖⁠י לְ⁠עָ֑ם וְ⁠שָׁכַנְתִּ֣י בְ⁠תוֹכֵ֔⁠ךְ וְ⁠יָדַ֕עַתְּ כִּי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֥⁠נִי אֵלָֽיִ⁠ךְ׃","wĕ⁠nilĕwẇ֩ gwòyi֨m rabi֤̇ym ʼel-yĕhwáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠há֥yẇ li֖⁠y lĕ⁠ʻá֑m wĕ⁠şá̌kanĕţi֣̇y bĕ⁠ţwòké֔⁠kĕ wĕ⁠yáda֕ʻaţĕ̇ ki̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֥⁠niy ʼéláֽyi⁠kĕ׃"],[2,12,"וְ⁠נָחַ֨ל יְהוָ֤ה אֶת־יְהוּדָה֙ חֶלְק֔⁠וֹ עַ֖ל אַדְמַ֣ת הַ⁠קֹּ֑דֶשׁ וּ⁠בָחַ֥ר ע֖וֹד בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠náẖa֨l yĕhwá֤h ʼeţ-yĕhẇdáh֙ ẖelĕq֔⁠wò ʻa֖l ʼadĕma֣ţ ha⁠qò֑̇deş̌ ẇ⁠báẖa֥r ʻ֖wòd bi̇⁠yrẇşá̌liáֽm׃"],[2,13,"הַ֥ס כָּל־בָּשָׂ֖ר מִ⁠פְּנֵ֣י יְהוָ֑ה כִּ֥י נֵע֖וֹר מִ⁠מְּע֥וֹן קָדְשֽׁ⁠וֹ׃ס","ha֥s ká̇l-bá̇şá֖̂r mi⁠pĕ̇né֣y yĕhwá֑h ki֥̇y néʻ֖wòr mi⁠mĕ̇ʻ֥wòn qádĕşֽ̌⁠wò׃s"],[3,1,"וַ⁠יַּרְאֵ֗⁠נִי אֶת־יְהוֹשֻׁ֨עַ֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל עֹמֵ֕ד לִ⁠פְנֵ֖י מַלְאַ֣ךְ יְהוָ֑ה וְ⁠הַ⁠שָּׂטָ֛ן עֹמֵ֥ד עַל־יְמִינ֖⁠וֹ לְ⁠שִׂטְנֽ⁠וֹ׃","wa⁠yȧrĕʼé֗⁠niy ʼeţ-yĕhwòşǔ֨ʻa֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl ʻòmé֕d li⁠pĕné֖y malĕʼa֣kĕ yĕhwá֑h wĕ⁠ha⁠şá̇̂tá֛n ʻòmé֥d ʻal-yĕmiyn֖⁠wò lĕ⁠şîtĕnֽ⁠wò׃"],[3,2,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־הַ⁠שָּׂטָ֗ן יִגְעַ֨ר יְהוָ֤ה בְּ⁠ךָ֙ הַ⁠שָּׂטָ֔ן וְ⁠יִגְעַ֤ר יְהוָה֙ בְּ⁠ךָ֔ הַ⁠בֹּחֵ֖ר בִּ⁠ירֽוּשָׁלִָ֑ם הֲ⁠ל֧וֹא זֶ֦ה א֖וּד מֻצָּ֥ל מֵ⁠אֵֽשׁ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-ha⁠şá̇̂tá֗n yigĕʻa֨r yĕhwá֤h bĕ̇⁠ká֙ ha⁠şá̇̂tá֔n wĕ⁠yigĕʻa֤r yĕhwáh֙ bĕ̇⁠ká֔ ha⁠bò̇ẖé֖r bi̇⁠yrֽẇşá̌liá֑m hà⁠l֧wòʼ ze֦h ʼ֖ẇd muẕá֥̇l mé⁠ʼéֽş̌׃"],[3,3,"וִ⁠יהוֹשֻׁ֕עַ הָיָ֥ה לָבֻ֖שׁ בְּגָדִ֣ים צוֹאִ֑ים וְ⁠עֹמֵ֖ד לִ⁠פְנֵ֥י הַ⁠מַּלְאָֽךְ׃","wi⁠yhwòşǔ֕ʻa háyá֥h lábu֖ş̌ bĕ̇gádi֣ym ẕwòʼi֑ym wĕ⁠ʻòmé֖d li⁠pĕné֥y ha⁠mȧlĕʼáֽkĕ׃"],[3,4,"וַ⁠יַּ֣עַן וַ⁠יֹּ֗אמֶר אֶל־הָ⁠עֹמְדִ֤ים לְ⁠פָנָי⁠ו֙ לֵ⁠אמֹ֔ר הָסִ֛ירוּ הַ⁠בְּגָדִ֥ים הַ⁠צֹּאִ֖ים מֵ⁠עָלָ֑י⁠ו וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו רְאֵ֨ה הֶעֱבַ֤רְתִּי מֵ⁠עָלֶ֨י⁠ךָ֙ עֲוֺנֶ֔⁠ךָ וְ⁠הַלְבֵּ֥שׁ אֹתְ⁠ךָ֖ מַחֲלָצֽוֹת׃","wa⁠yȧ֣ʻan wa⁠yò̇֗ʼmer ʼel-há⁠ʻòmĕdi֤ym lĕ⁠pánáy⁠w֙ lé⁠ʼmò֔r hási֛yrẇ ha⁠bĕ̇gádi֥ym ha⁠ẕò̇ʼi֖ym mé⁠ʻálá֑y⁠w wa⁠yò֣̇ʼmer ʼélá֗y⁠w rĕʼé֨h heʻèba֤rĕţi̇y mé⁠ʻále֨y⁠ká֙ ʻàwֺne֔⁠ká wĕ⁠halĕbé֥̇ş̌ ʼòţĕ⁠ká֖ maẖàláẕֽwòţ׃"],[3,5,"וָ⁠אֹמַ֕ר יָשִׂ֛ימוּ צָנִ֥יף טָה֖וֹר עַל־רֹאשׁ֑⁠וֹ וַ⁠יָּשִׂימוּ֩ הַ⁠צָּנִ֨יף הַ⁠טָּה֜וֹר עַל־רֹאשׁ֗⁠וֹ וַ⁠יַּלְבִּשֻׁ֨⁠הוּ֙ בְּגָדִ֔ים וּ⁠מַלְאַ֥ךְ יְהוָ֖ה עֹמֵֽד׃","wá⁠ʼòma֕r yáşî֛ymẇ ẕáni֥yp táh֖wòr ʻal-ròʼş֑̌⁠wò wa⁠yá̇şîymẇ֩ ha⁠ẕá̇ni֨yp ha⁠tá̇h֜wòr ʻal-ròʼş̌֗⁠wò wa⁠yȧlĕbi̇şǔ֨⁠hẇ֙ bĕ̇gádi֔ym ẇ⁠malĕʼa֥kĕ yĕhwá֖h ʻòméֽd׃"],[3,6,"וַ⁠יָּ֨עַד֙ מַלְאַ֣ךְ יְהוָ֔ה בִּ⁠יהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wa⁠yá̇֨ʻad֙ malĕʼa֣kĕ yĕhwá֔h bi̇⁠yhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[3,7,"כֹּה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת אִם־בִּ⁠דְרָכַ֤⁠י תֵּלֵךְ֙ וְ⁠אִ֣ם אֶת־מִשְׁמַרְתִּ֣⁠י תִשְׁמֹ֔ר וְ⁠גַם־אַתָּה֙ תָּדִ֣ין אֶת־בֵּיתִ֔⁠י וְ⁠גַ֖ם תִּשְׁמֹ֣ר אֶת־חֲצֵרָ֑⁠י וְ⁠נָתַתִּ֤י לְ⁠ךָ֙ מַהְלְכִ֔ים בֵּ֥ין הָ⁠עֹמְדִ֖ים הָ⁠אֵֽלֶּה׃","kò̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ʼim-bi̇⁠dĕráka֤⁠y ţé̇lékĕ֙ wĕ⁠ʼi֣m ʼeţ-mişĕ̌marĕţi֣̇⁠y ţişĕ̌mò֔r wĕ⁠gam-ʼaţá̇h֙ ţá̇di֣yn ʼeţ-bé̇yţi֔⁠y wĕ⁠ga֖m ţi̇şĕ̌mò֣r ʼeţ-ẖàẕérá֑⁠y wĕ⁠náţaţi֤̇y lĕ⁠ká֙ mahĕlĕki֔ym bé֥̇yn há⁠ʻòmĕdi֖ym há⁠ʼéֽlėh׃"],[3,8,"שְֽׁמַֽע־נָ֞א יְהוֹשֻׁ֣עַ ׀ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֗וֹל אַתָּה֙ וְ⁠רֵעֶ֨י⁠ךָ֙ הַ⁠יֹּשְׁבִ֣ים לְ⁠פָנֶ֔י⁠ךָ כִּֽי־אַנְשֵׁ֥י מוֹפֵ֖ת הֵ֑מָּה כִּֽי־הִנְ⁠נִ֥י מֵבִ֛יא אֶת־עַבְדִּ֖⁠י צֶֽמַח׃","şĕֽ̌maֽʻ-ná֞ʼ yĕhwòşǔ֣ʻa ׀ ha⁠kò̇hé֣n ha⁠gá̇d֗wòl ʼaţá̇h֙ wĕ⁠réʻe֨y⁠ká֙ ha⁠yò̇şĕ̌bi֣ym lĕ⁠páne֔y⁠ká kiֽ̇y-ʼanĕşé֥̌y mwòpé֖ţ hé֑má̇h kiֽ̇y-hinĕ⁠ni֥y mébi֛yʼ ʼeţ-ʻabĕdi֖̇⁠y ẕeֽmaẖ׃"],[3,9,"כִּ֣י ׀ הִנֵּ֣ה הָ⁠אֶ֗בֶן אֲשֶׁ֤ר נָתַ֨תִּי֙ לִ⁠פְנֵ֣י יְהוֹשֻׁ֔עַ עַל־אֶ֥בֶן אַחַ֖ת שִׁבְעָ֣ה עֵינָ֑יִם הִנְ⁠נִ֧י מְפַתֵּ֣חַ פִּתֻּחָ֗⁠הּ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠מַשְׁתִּ֛י אֶת־עֲוֺ֥ן הָ⁠אָֽרֶץ־הַ⁠הִ֖יא בְּ⁠י֥וֹם אֶחָֽד׃","ki֣̇y ׀ hiné֣̇h há⁠ʼe֗ben ʼàşě֤r náţa֨ţi̇y֙ li⁠pĕné֣y yĕhwòşǔ֔ʻa ʻal-ʼe֥ben ʼaẖa֖ţ şǐbĕʻá֣h ʻéyná֑yim hinĕ⁠ni֧y mĕpaţé֣̇ẖa pi̇ţu̇ẖá֗⁠ḣ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠maşĕ̌ţi֛̇y ʼeţ-ʻàwֺ֥n há⁠ʼáֽreẕ-ha⁠hi֖yʼ bĕ̇⁠y֥wòm ʼeẖáֽd׃"],[3,10,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת תִּקְרְא֖וּ אִ֣ישׁ לְ⁠רֵעֵ֑⁠הוּ אֶל־תַּ֥חַת גֶּ֖פֶן וְ⁠אֶל־תַּ֥חַת תְּאֵנָֽה׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ţi̇qĕrĕʼ֖ẇ ʼi֣yş̌ lĕ⁠réʻé֑⁠hẇ ʼel-ţȧ֥ẖaţ gė֖pen wĕ⁠ʼel-ţȧ֥ẖaţ ţĕ̇ʼénáֽh׃"],[4,1,"וַ⁠יָּ֕שָׁב הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י וַ⁠יְעִירֵ֕⁠נִי כְּ⁠אִ֖ישׁ אֲשֶׁר־יֵע֥וֹר מִ⁠שְּׁנָתֽ⁠וֹ׃","wa⁠yá̇֕şá̌b ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y wa⁠yĕʻiyré֕⁠niy kĕ̇⁠ʼi֖yş̌ ʼàşěr-yéʻ֥wòr mi⁠şĕ̇̌náţֽ⁠wò׃"],[4,2,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י מָ֥ה אַתָּ֖ה רֹאֶ֑ה ו⁠יאמר רָאִ֣יתִי ׀ וְ⁠הִנֵּ֣ה מְנוֹרַת֩ זָהָ֨ב כֻּלָּ֜⁠הּ וְ⁠גֻלָּ֣הּ עַל־רֹאשָׁ֗⁠הּ וְ⁠שִׁבְעָ֤ה נֵרֹתֶ֨י⁠הָ֙ עָלֶ֔י⁠הָ שִׁבְעָ֤ה וְ⁠שִׁבְעָה֙ מֽוּצָק֔וֹת לַ⁠נֵּר֖וֹת אֲשֶׁ֥ר עַל־רֹאשָֽׁ⁠הּ׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y má֥h ʼaţá֖̇h ròʼe֑h w⁠yʼmr ráʼi֣yţiy ׀ wĕ⁠hiné֣̇h mĕnwòraţ֩ záhá֨b ku̇lá̇֜⁠ḣ wĕ⁠gulá֣̇ḣ ʻal-ròʼşá̌֗⁠ḣ wĕ⁠şǐbĕʻá֤h néròţe֨y⁠há֙ ʻále֔y⁠há şǐbĕʻá֤h wĕ⁠şǐbĕʻáh֙ mֽẇẕáq֔wòţ la⁠né̇r֖wòţ ʼàşě֥r ʻal-ròʼşáֽ̌⁠ḣ׃"],[4,3,"וּ⁠שְׁנַ֥יִם זֵיתִ֖ים עָלֶ֑י⁠הָ אֶחָד֙ מִ⁠ימִ֣ין הַ⁠גֻּלָּ֔ה וְ⁠אֶחָ֖ד עַל־שְׂמֹאלָֽ⁠הּ׃","ẇ⁠şĕ̌na֥yim zéyţi֖ym ʻále֑y⁠há ʼeẖád֙ mi⁠ymi֣yn ha⁠gu̇lá̇֔h wĕ⁠ʼeẖá֖d ʻal-şĕ̂mòʼláֽ⁠ḣ׃"],[4,4,"וָ⁠אַ֨עַן֙ וָֽ⁠אֹמַ֔ר אֶל־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י לֵ⁠אמֹ֑ר מָה־אֵ֖לֶּה אֲדֹנִֽ⁠י׃","wá⁠ʼa֨ʻan֙ wáֽ⁠ʼòma֔r ʼel-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y lé⁠ʼmò֑r máh-ʼé֖lėh ʼàdòniֽ⁠y׃"],[4,5,"וַ֠⁠יַּעַן הַ⁠מַּלְאָ֞ךְ הַ⁠דֹּבֵ֥ר בִּ⁠י֙ וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י הֲ⁠ל֥וֹא יָדַ֖עְתָּ מָה־הֵ֣מָּה אֵ֑לֶּה וָ⁠אֹמַ֖ר לֹ֥א אֲדֹנִֽ⁠י׃","wa֠⁠yȧʻan ha⁠mȧlĕʼá֞kĕ ha⁠dò̇bé֥r bi̇⁠y֙ wa⁠yò֣̇ʼmer ʼéla֔⁠y hà⁠l֥wòʼ yáda֖ʻĕţá̇ máh-hé֣má̇h ʼé֑lėh wá⁠ʼòma֖r lò֥ʼ ʼàdòniֽ⁠y׃"],[4,6,"וַ⁠יַּ֜עַן וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ לֵ⁠אמֹ֔ר זֶ֚ה דְּבַר־יְהוָ֔ה אֶל־זְרֻבָּבֶ֖ל לֵ⁠אמֹ֑ר לֹ֤א בְ⁠חַ֨יִל֙ וְ⁠לֹ֣א בְ⁠כֹ֔חַ כִּ֣י אִם־בְּ⁠רוּחִ֔⁠י אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wa⁠yȧ֜ʻan wa⁠yò֤̇ʼmer ʼéla⁠y֙ lé⁠ʼmò֔r ze֚h dĕ̇bar-yĕhwá֔h ʼel-zĕrubá̇be֖l lé⁠ʼmò֑r lò֤ʼ bĕ⁠ẖa֨yil֙ wĕ⁠lò֣ʼ bĕ⁠kò֔ẖa ki֣̇y ʼim-bĕ̇⁠rẇẖi֔⁠y ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[4,7,"מִֽי־אַתָּ֧ה הַֽר־הַ⁠גָּד֛וֹל לִ⁠פְנֵ֥י זְרֻבָּבֶ֖ל לְ⁠מִישֹׁ֑ר וְ⁠הוֹצִיא֙ אֶת־הָ⁠אֶ֣בֶן הָ⁠רֹאשָׁ֔ה תְּשֻׁא֕וֹת חֵ֥ן חֵ֖ן לָֽ⁠הּ׃פ","miֽy-ʼaţá֧̇h haֽr-ha⁠gá̇d֛wòl li⁠pĕné֥y zĕrubá̇be֖l lĕ⁠miyşò֑̌r wĕ⁠hwòẕiyʼ֙ ʼeţ-há⁠ʼe֣ben há⁠ròʼşá̌֔h ţĕ̇şǔʼ֕wòţ ẖé֥n ẖé֖n láֽ⁠ḣ׃p"],[4,8,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[4,9,"יְדֵ֣י זְרֻבָּבֶ֗ל יִסְּד֛וּ הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה וְ⁠יָדָ֣י⁠ו תְּבַצַּ֑עְנָה וְ⁠יָ֣דַעְתָּ֔ כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֥⁠נִי אֲלֵי⁠כֶֽם׃","yĕdé֣y zĕrubá̇be֗l yisĕ̇d֛ẇ ha⁠bȧ֥yiţ ha⁠zė֖h wĕ⁠yádá֣y⁠w ţĕ̇baẕȧ֑ʻĕnáh wĕ⁠yá֣daʻĕţá̇֔ kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֥⁠niy ʼàléy⁠keֽm׃"],[4,10,"כִּ֣י מִ֣י בַז֮ לְ⁠י֣וֹם קְטַנּוֹת֒ וְ⁠שָׂמְח֗וּ וְ⁠רָא֞וּ אֶת־הָ⁠אֶ֧בֶן הַ⁠בְּדִ֛יל בְּ⁠יַ֥ד זְרֻבָּבֶ֖ל שִׁבְעָה־אֵ֑לֶּה עֵינֵ֣י יְהוָ֔ה הֵ֥מָּה מְשׁוֹטְטִ֖ים בְּ⁠כָל־הָ⁠אָֽרֶץ׃","ki֣̇y mi֣y baz֮ lĕ⁠y֣wòm qĕtaṅwòţ֒ wĕ⁠şá̂mĕẖ֗ẇ wĕ⁠ráʼ֞ẇ ʼeţ-há⁠ʼe֧ben ha⁠bĕ̇di֛yl bĕ̇⁠ya֥d zĕrubá̇be֖l şǐbĕʻáh-ʼé֑lėh ʻéyné֣y yĕhwá֔h hé֥má̇h mĕş̌wòtĕti֖ym bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[4,11,"וָ⁠אַ֖עַן וָ⁠אֹמַ֣ר אֵלָ֑י⁠ו מַה־שְּׁנֵ֤י הַ⁠זֵּיתִים֙ הָ⁠אֵ֔לֶה עַל־יְמִ֥ין הַ⁠מְּנוֹרָ֖ה וְ⁠עַל־שְׂמֹאולָֽ⁠הּ׃","wá⁠ʼa֖ʻan wá⁠ʼòma֣r ʼélá֑y⁠w mah-şĕ̇̌né֤y ha⁠zé̇yţiym֙ há⁠ʼé֔leh ʻal-yĕmi֥yn ha⁠mĕ̇nwòrá֖h wĕ⁠ʻal-şĕ̂mòʼwláֽ⁠ḣ׃"],[4,12,"וָ⁠אַ֣עַן שֵׁנִ֔ית וָ⁠אֹמַ֖ר אֵלָ֑י⁠ו מַה־שְׁתֵּ֞י שִׁבֲּלֵ֣י הַ⁠זֵּיתִ֗ים אֲשֶׁר֙ בְּ⁠יַ֗ד שְׁנֵי֙ צַנְתְּר֣וֹת הַ⁠זָּהָ֔ב הַֽ⁠מְרִיקִ֥ים מֵ⁠עֲלֵי⁠הֶ֖ם הַ⁠זָּהָֽב׃","wá⁠ʼa֣ʻan şé̌ni֔yţ wá⁠ʼòma֖r ʼélá֑y⁠w mah-şĕ̌ţé̇֞y şǐbà̇lé֣y ha⁠zé̇yţi֗ym ʼàşěr֙ bĕ̇⁠ya֗d şĕ̌néy֙ ẕanĕţĕ̇r֣wòţ ha⁠zá̇há֔b haֽ⁠mĕriyqi֥ym mé⁠ʻàléy⁠he֖m ha⁠zá̇háֽb׃"],[4,13,"וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ לֵ⁠אמֹ֔ר הֲ⁠ל֥וֹא יָדַ֖עְתָּ מָה־אֵ֑לֶּה וָ⁠אֹמַ֖ר לֹ֥א אֲדֹנִֽ⁠י׃","wa⁠yò֤̇ʼmer ʼéla⁠y֙ lé⁠ʼmò֔r hà⁠l֥wòʼ yáda֖ʻĕţá̇ máh-ʼé֑lėh wá⁠ʼòma֖r lò֥ʼ ʼàdòniֽ⁠y׃"],[4,14,"וַ⁠יֹּ֕אמֶר אֵ֖לֶּה שְׁנֵ֣י בְנֵֽי־הַ⁠יִּצְהָ֑ר הָ⁠עֹמְדִ֖ים עַל־אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","wa⁠yò̇֕ʼmer ʼé֖lėh şĕ̌né֣y bĕnéֽy-ha⁠yi̇ẕĕhá֑r há⁠ʻòmĕdi֖ym ʻal-ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[5,1,"וָ⁠אָשׁ֕וּב וָ⁠אֶשָּׂ֥א עֵינַ֖⁠י וָֽ⁠אֶרְאֶ֑ה וְ⁠הִנֵּ֖ה מְגִלָּ֥ה עָפָֽה׃","wá⁠ʼáş̌֕ẇb wá⁠ʼeşá֥̇̂ʼ ʻéyna֖⁠y wáֽ⁠ʼerĕʼe֑h wĕ⁠hiné֖̇h mĕgilá֥̇h ʻápáֽh׃"],[5,2,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י מָ֥ה אַתָּ֖ה רֹאֶ֑ה וָ⁠אֹמַ֗ר אֲנִ֤י רֹאֶה֙ מְגִלָּ֣ה עָפָ֔ה אָרְכָּ⁠הּ֙ עֶשְׂרִ֣ים בָּֽ⁠אַמָּ֔ה וְ⁠רָחְבָּ֖⁠הּ עֶ֥שֶׂר בָּ⁠אַמָּֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y má֥h ʼaţá֖̇h ròʼe֑h wá⁠ʼòma֗r ʼàni֤y ròʼeh֙ mĕgilá֣̇h ʻápá֔h ʼárĕká̇⁠ḣ֙ ʻeşĕ̂ri֣ym báֽ̇⁠ʼamá̇֔h wĕ⁠ráẖĕbá֖̇⁠ḣ ʻe֥şêr bá̇⁠ʼamáֽ̇h׃"],[5,3,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י זֹ֚את הָֽ⁠אָלָ֔ה הַ⁠יּוֹצֵ֖את עַל־פְּנֵ֣י כָל־הָ⁠אָ֑רֶץ כִּ֣י כָל־הַ⁠גֹּנֵ֗ב מִ⁠זֶּה֙ כָּמ֣וֹ⁠הָ נִקָּ֔ה וְ⁠כָל־הַ⁠נִּ֨שְׁבָּ֔ע מִ⁠זֶּ֖ה כָּמ֥וֹ⁠הָ נִקָּֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y zò֚ʼţ háֽ⁠ʼálá֔h ha⁠ẏwòẕé֖ʼţ ʻal-pĕ̇né֣y kál-há⁠ʼá֑reẕ ki֣̇y kál-ha⁠gò̇né֗b mi⁠zėh֙ ká̇m֣wò⁠há niqá̇֔h wĕ⁠kál-ha⁠ni̇֨şĕ̌bá̇֔ʻ mi⁠zė֖h ká̇m֥wò⁠há niqáֽ̇h׃"],[5,4,"הוֹצֵאתִ֗י⁠הָ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠בָ֨אָה֙ אֶל־בֵּ֣ית הַ⁠גַּנָּ֔ב וְ⁠אֶל־בֵּ֛ית הַ⁠נִּשְׁבָּ֥ע בִּ⁠שְׁמִ֖⁠י לַ⁠שָּׁ֑קֶר וְ⁠לָ֨נֶה֙ בְּ⁠ת֣וֹךְ בֵּית֔⁠וֹ וְ⁠כִלַּ֖תּ⁠וּ וְ⁠אֶת־עֵצָ֥י⁠ו וְ⁠אֶת־אֲבָנָֽי⁠ו׃","hwòẕéʼţi֗y⁠há nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠bá֨ʼáh֙ ʼel-bé֣̇yţ ha⁠gȧná̇֔b wĕ⁠ʼel-bé֛̇yţ ha⁠ni̇şĕ̌bá֥̇ʻ bi̇⁠şĕ̌mi֖⁠y la⁠şá֑̇̌qer wĕ⁠lá֨neh֙ bĕ̇⁠ţ֣wòkĕ bé̇yţ֔⁠wò wĕ⁠kilȧ֖ţ̇⁠ẇ wĕ⁠ʼeţ-ʻéẕá֥y⁠w wĕ⁠ʼeţ-ʼàbánáֽy⁠w׃"],[5,5,"וַ⁠יֵּצֵ֕א הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י שָׂ֣א נָ֤א עֵינֶ֨י⁠ךָ֙ וּ⁠רְאֵ֔ה מָ֖ה הַ⁠יּוֹצֵ֥את הַ⁠זֹּֽאת׃","wa⁠yé̇ẕé֕ʼ ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y wa⁠yò֣̇ʼmer ʼéla֔⁠y şá֣̂ʼ ná֤ʼ ʻéyne֨y⁠ká֙ ẇ⁠rĕʼé֔h má֖h ha⁠ẏwòẕé֥ʼţ ha⁠zòֽ̇ʼţ׃"],[5,6,"וָ⁠אֹמַ֖ר מַה־הִ֑יא וַ⁠יֹּ֗אמֶר זֹ֤את הָֽ⁠אֵיפָה֙ הַ⁠יּוֹצֵ֔את וַ⁠יֹּ֕אמֶר זֹ֥את עֵינָ֖⁠ם בְּ⁠כָל־הָ⁠אָֽרֶץ׃","wá⁠ʼòma֖r mah-hi֑yʼ wa⁠yò̇֗ʼmer zò֤ʼţ háֽ⁠ʼéypáh֙ ha⁠ẏwòẕé֔ʼţ wa⁠yò̇֕ʼmer zò֥ʼţ ʻéyná֖⁠m bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[5,7,"וְ⁠הִנֵּ֛ה כִּכַּ֥ר עֹפֶ֖רֶת נִשֵּׂ֑את וְ⁠זֹאת֙ אִשָּׁ֣ה אַחַ֔ת יוֹשֶׁ֖בֶת בְּ⁠ת֥וֹךְ הָ⁠אֵיפָֽה׃","wĕ⁠hiné֛̇h ki̇kȧ֥r ʻòpe֖reţ nişé֑̇̂ʼţ wĕ⁠zòʼţ֙ ʼişá֣̇̌h ʼaẖa֔ţ ywòşě֖beţ bĕ̇⁠ţ֥wòkĕ há⁠ʼéypáֽh׃"],[5,8,"וַ⁠יֹּ֨אמֶר֙ זֹ֣את הָ⁠רִשְׁעָ֔ה וַ⁠יַּשְׁלֵ֥ךְ אֹתָ֖⁠הּ אֶל־תּ֣וֹךְ הָֽ⁠אֵיפָ֑ה וַ⁠יַּשְׁלֵ֛ךְ אֶת־אֶ֥בֶן הָ⁠עֹפֶ֖רֶת אֶל־פִּֽי⁠הָ׃ס","wa⁠yò̇֨ʼmer֙ zò֣ʼţ há⁠rişĕ̌ʻá֔h wa⁠yȧşĕ̌lé֥kĕ ʼòţá֖⁠ḣ ʼel-ţ֣̇wòkĕ háֽ⁠ʼéypá֑h wa⁠yȧşĕ̌lé֛kĕ ʼeţ-ʼe֥ben há⁠ʻòpe֖reţ ʼel-piֽ̇y⁠há׃s"],[5,9,"וָ⁠אֶשָּׂ֨א עֵינַ֜⁠י וָ⁠אֵ֗רֶא וְ⁠הִנֵּה֩ שְׁתַּ֨יִם נָשִׁ֤ים יֽוֹצְאוֹת֙ וְ⁠ר֣וּחַ בְּ⁠כַנְפֵי⁠הֶ֔ם וְ⁠לָ⁠הֵ֥נָּה כְנָפַ֖יִם כְּ⁠כַנְפֵ֣י הַ⁠חֲסִידָ֑ה וַ⁠תִּשֶּׂ֨אנָה֙ אֶת־הָ֣⁠אֵיפָ֔ה בֵּ֥ין הָ⁠אָ֖רֶץ וּ⁠בֵ֥ין הַ⁠שָּׁמָֽיִם׃","wá⁠ʼeşá̇̂֨ʼ ʻéyna֜⁠y wá⁠ʼé֗reʼ wĕ⁠hiné̇h֩ şĕ̌ţȧ֨yim náşǐ֤ym yֽwòẕĕʼwòţ֙ wĕ⁠r֣ẇẖa bĕ̇⁠kanĕpéy⁠he֔m wĕ⁠lá⁠hé֥ná̇h kĕnápa֖yim kĕ̇⁠kanĕpé֣y ha⁠ẖàsiydá֑h wa⁠ţi̇şė̂֨ʼnáh֙ ʼeţ-há֣⁠ʼéypá֔h bé֥̇yn há⁠ʼá֖reẕ ẇ⁠bé֥yn ha⁠şá̇̌máֽyim׃"],[5,10,"וָ⁠אֹמַ֕ר אֶל־הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י אָ֛נָה הֵ֥מָּה מֽוֹלִכ֖וֹת אֶת־הָ⁠אֵיפָֽה׃","wá⁠ʼòma֕r ʼel-ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y ʼá֛náh hé֥má̇h mֽwòlik֖wòţ ʼeţ-há⁠ʼéypáֽh׃"],[5,11,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י לִ⁠בְנֽוֹת־לָ֥⁠הֿ בַ֖יִת בְּ⁠אֶ֣רֶץ שִׁנְעָ֑ר וְ⁠הוּכַ֛ן וְ⁠הֻנִּ֥יחָה שָּׁ֖ם עַל־מְכֻנָתָֽ⁠הּ׃ס","wa⁠yò֣̇ʼmer ʼéla֔⁠y li⁠bĕnֽwòţ-lá֥⁠h̄ ba֖yiţ bĕ̇⁠ʼe֣reẕ şǐnĕʻá֑r wĕ⁠hẇka֛n wĕ⁠huni֥̇yẖáh şá֖̇̌m ʻal-mĕkunáţáֽ⁠ḣ׃s"],[6,1,"וָ⁠אָשֻׁ֗ב וָ⁠אֶשָּׂ֤א עֵינַ⁠י֙ וָֽ⁠אֶרְאֶ֔ה וְ⁠הִנֵּ֨ה אַרְבַּ֤ע מַרְכָּבוֹת֙ יֹֽצְא֔וֹת מִ⁠בֵּ֖ין שְׁנֵ֣י הֶֽ⁠הָרִ֑ים וְ⁠הֶ⁠הָרִ֖ים הָרֵ֥י נְחֹֽשֶׁת׃","wá⁠ʼáşǔ֗b wá⁠ʼeşá֤̇̂ʼ ʻéyna⁠y֙ wáֽ⁠ʼerĕʼe֔h wĕ⁠hiné̇֨h ʼarĕbȧ֤ʻ marĕká̇bwòţ֙ yòֽẕĕʼ֔wòţ mi⁠bé֖̇yn şĕ̌né֣y heֽ⁠hári֑ym wĕ⁠he⁠hári֖ym háré֥y nĕẖòֽşěţ׃"],[6,2,"בַּ⁠מֶּרְכָּבָ֥ה הָ⁠רִֽאשֹׁנָ֖ה סוּסִ֣ים אֲדֻמִּ֑ים וּ⁠בַ⁠מֶּרְכָּבָ֥ה הַ⁠שֵּׁנִ֖ית סוּסִ֥ים שְׁחֹרִֽים׃","bȧ⁠mėrĕká̇bá֥h há⁠riֽʼşò̌ná֖h sẇsi֣ym ʼàdumi֑̇ym ẇ⁠ba⁠mėrĕká̇bá֥h ha⁠şé̇̌ni֖yţ sẇsi֥ym şĕ̌ẖòriֽym׃"],[6,3,"וּ⁠בַ⁠מֶּרְכָּבָ֥ה הַ⁠שְּׁלִשִׁ֖ית סוּסִ֣ים לְבָנִ֑ים וּ⁠בַ⁠מֶּרְכָּבָה֙ הָ⁠רְבִעִ֔ית סוּסִ֥ים בְּרֻדִּ֖ים אֲמֻצִּֽים׃","ẇ⁠ba⁠mėrĕká̇bá֥h ha⁠şĕ̇̌lişǐ֖yţ sẇsi֣ym lĕbáni֑ym ẇ⁠ba⁠mėrĕká̇báh֙ há⁠rĕbiʻi֔yţ sẇsi֥ym bĕ̇rudi֖̇ym ʼàmuẕiֽ̇ym׃"],[6,4,"וָ⁠אַ֨עַן֙ וָֽ⁠אֹמַ֔ר אֶל־הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י מָה־אֵ֖לֶּה אֲדֹנִֽ⁠י׃","wá⁠ʼa֨ʻan֙ wáֽ⁠ʼòma֔r ʼel-ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y máh-ʼé֖lėh ʼàdòniֽ⁠y׃"],[6,5,"וַ⁠יַּ֥עַן הַ⁠מַּלְאָ֖ךְ וַ⁠יֹּ֣אמֶר אֵלָ֑⁠י אֵ֗לֶּה אַרְבַּע֙ רֻח֣וֹת הַ⁠שָּׁמַ֔יִם יוֹצְא֕וֹת מֵֽ⁠הִתְיַצֵּ֖ב עַל־אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","wa⁠yȧ֥ʻan ha⁠mȧlĕʼá֖kĕ wa⁠yò֣̇ʼmer ʼélá֑⁠y ʼé֗lėh ʼarĕbȧʻ֙ ruẖ֣wòţ ha⁠şá̇̌ma֔yim ywòẕĕʼ֕wòţ méֽ⁠hiţĕyaẕé֖̇b ʻal-ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[6,6,"אֲשֶׁר־בָּ֞⁠הּ הַ⁠סּוּסִ֣ים הַ⁠שְּׁחֹרִ֗ים יֹֽצְאִים֙ אֶל־אֶ֣רֶץ צָפ֔וֹן וְ⁠הַ⁠לְּבָנִ֔ים יָצְא֖וּ אֶל־אַֽחֲרֵי⁠הֶ֑ם וְ⁠הַ֨⁠בְּרֻדִּ֔ים יָצְא֖וּ אֶל־אֶ֥רֶץ הַ⁠תֵּימָֽן׃","ʼàşěr-bá̇֞⁠ḣ ha⁠ṡẇsi֣ym ha⁠şĕ̇̌ẖòri֗ym yòֽẕĕʼiym֙ ʼel-ʼe֣reẕ ẕáp֔wòn wĕ⁠ha⁠lĕ̇báni֔ym yáẕĕʼ֖ẇ ʼel-ʼaֽẖàréy⁠he֑m wĕ⁠ha֨⁠bĕ̇rudi̇֔ym yáẕĕʼ֖ẇ ʼel-ʼe֥reẕ ha⁠ţé̇ymáֽn׃"],[6,7,"וְ⁠הָ⁠אֲמֻצִּ֣ים יָצְא֗וּ וַ⁠יְבַקְשׁוּ֙ לָ⁠לֶ֨כֶת֙ לְ⁠הִתְהַלֵּ֣ך בָּ⁠אָ֔רֶץ וַ⁠יֹּ֕אמֶר לְכ֖וּ הִתְהַלְּכ֣וּ בָ⁠אָ֑רֶץ וַ⁠תִּתְהַלַּ֖כְנָה בָּ⁠אָֽרֶץ׃","wĕ⁠há⁠ʼàmuẕi֣̇ym yáẕĕʼ֗ẇ wa⁠yĕbaqĕş̌ẇ֙ lá⁠le֨keţ֙ lĕ⁠hiţĕhalé֣̇k bá̇⁠ʼá֔reẕ wa⁠yò̇֕ʼmer lĕk֖ẇ hiţĕhalĕ̇k֣ẇ bá⁠ʼá֑reẕ wa⁠ţi̇ţĕhalȧ֖kĕnáh bá̇⁠ʼáֽreẕ׃"],[6,8,"וַ⁠יַּזְעֵ֣ק אֹתִ֔⁠י וַ⁠יְדַבֵּ֥ר אֵלַ֖⁠י לֵ⁠אמֹ֑ר רְאֵ֗ה הַ⁠יּֽוֹצְאִים֙ אֶל־אֶ֣רֶץ צָפ֔וֹן הֵנִ֥יחוּ אֶת־רוּחִ֖⁠י בְּ⁠אֶ֥רֶץ צָפֽוֹן׃ס","wa⁠yȧzĕʻé֣q ʼòţi֔⁠y wa⁠yĕdabé֥̇r ʼéla֖⁠y lé⁠ʼmò֑r rĕʼé֗h ha⁠ẏֽwòẕĕʼiym֙ ʼel-ʼe֣reẕ ẕáp֔wòn héni֥yẖẇ ʼeţ-rẇẖi֖⁠y bĕ̇⁠ʼe֥reẕ ẕápֽwòn׃s"],[6,9,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[6,10,"לָק֨וֹחַ֙ מֵ⁠אֵ֣ת הַ⁠גּוֹלָ֔ה מֵ⁠חֶלְדַּ֕י וּ⁠מֵ⁠אֵ֥ת טוֹבִיָּ֖ה וּ⁠מֵ⁠אֵ֣ת יְדַֽעְיָ֑ה וּ⁠בָאתָ֤ אַתָּה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וּ⁠בָ֗אתָ בֵּ֚ית יֹאשִׁיָּ֣ה בֶן־צְפַנְיָ֔ה אֲשֶׁר־בָּ֖אוּ מִ⁠בָּבֶֽל׃","láq֨wòẖa֙ mé⁠ʼé֣ţ ha⁠ġwòlá֔h mé⁠ẖelĕdȧ֕y ẇ⁠mé⁠ʼé֥ţ twòbiyá֖̇h ẇ⁠mé⁠ʼé֣ţ yĕdaֽʻĕyá֑h ẇ⁠báʼţá֤ ʼaţá̇h֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ẇ⁠bá֗ʼţá bé֚̇yţ yòʼşǐyá֣̇h ben-ẕĕpanĕyá֔h ʼàşěr-bá֖̇ʼẇ mi⁠bá̇beֽl׃"],[6,11,"וְ⁠לָקַחְתָּ֥ כֶֽסֶף־וְ⁠זָהָ֖ב וְ⁠עָשִׂ֣יתָ עֲטָר֑וֹת וְ⁠שַׂמְתָּ֗ בְּ⁠רֹ֛אשׁ יְהוֹשֻׁ֥עַ בֶּן־יְהוֹצָדָ֖ק הַ⁠כֹּהֵ֥ן הַ⁠גָּדֽוֹל׃","wĕ⁠láqaẖĕţá֥̇ keֽsep-wĕ⁠záhá֖b wĕ⁠ʻáşî֣yţá ʻàtár֑wòţ wĕ⁠şâmĕţá̇֗ bĕ̇⁠rò֛ʼş̌ yĕhwòşǔ֥ʻa bėn-yĕhwòẕádá֖q ha⁠kò̇hé֥n ha⁠gá̇dֽwòl׃"],[6,12,"וְ⁠אָמַרְתָּ֤ אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר הִנֵּה־אִ֞ישׁ צֶ֤מַח שְׁמ⁠וֹ֙ וּ⁠מִ⁠תַּחְתָּ֣י⁠ו יִצְמָ֔ח וּ⁠בָנָ֖ה אֶת־הֵיכַ֥ל יְהוָֽהּ׃","wĕ⁠ʼámarĕţá֤̇ ʼéláy⁠w֙ lé⁠ʼmò֔r kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r hiné̇h-ʼi֞yş̌ ẕe֤maẖ şĕ̌m⁠wò֙ ẇ⁠mi⁠ţȧẖĕţá֣̇y⁠w yiẕĕmá֔ẖ ẇ⁠báná֖h ʼeţ-héyka֥l yĕhwáֽḣ׃"],[6,13,"וְ֠⁠הוּא יִבְנֶ֞ה אֶת־הֵיכַ֤ל יְהוָה֙ וְ⁠הֽוּא־יִשָּׂ֣א ה֔וֹד וְ⁠יָשַׁ֥ב וּ⁠מָשַׁ֖ל עַל־כִּסְא֑⁠וֹ וְ⁠הָיָ֤ה כֹהֵן֙ עַל־כִּסְא֔⁠וֹ וַ⁠עֲצַ֣ת שָׁל֔וֹם תִּהְיֶ֖ה בֵּ֥ין שְׁנֵי⁠הֶֽם׃","wĕ֠⁠hẇʼ yibĕne֞h ʼeţ-héyka֤l yĕhwáh֙ wĕ⁠hֽẇʼ-yişá֣̇̂ʼ h֔wòd wĕ⁠yáşǎ֥b ẇ⁠máşǎ֖l ʻal-ki̇sĕʼ֑⁠wò wĕ⁠háyá֤h kòhén֙ ʻal-ki̇sĕʼ֔⁠wò wa⁠ʻàẕa֣ţ şá̌l֔wòm ţi̇hĕye֖h bé֥̇yn şĕ̌néy⁠heֽm׃"],[6,14,"וְ⁠הָ⁠עֲטָרֹ֗ת תִּֽהְיֶה֙ לְ⁠חֵ֨לֶם֙ וּ⁠לְ⁠טוֹבִיָּ֣ה וְ⁠לִ⁠ידַֽעְיָ֔ה וּ⁠לְ⁠חֵ֖ן בֶּן־צְפַנְיָ֑ה לְ⁠זִכָּר֖וֹן בְּ⁠הֵיכַ֥ל יְהוָֽה׃","wĕ⁠há⁠ʻàtárò֗ţ ţiֽ̇hĕyeh֙ lĕ⁠ẖé֨lem֙ ẇ⁠lĕ⁠twòbiyá֣̇h wĕ⁠li⁠ydaֽʻĕyá֔h ẇ⁠lĕ⁠ẖé֖n bėn-ẕĕpanĕyá֑h lĕ⁠ziká̇r֖wòn bĕ̇⁠héyka֥l yĕhwáֽh׃"],[6,15,"וּ⁠רְחוֹקִ֣ים ׀ יָבֹ֗אוּ וּ⁠בָנוּ֙ בְּ⁠הֵיכַ֣ל יְהוָ֔ה וִ⁠ידַעְתֶּ֕ם כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֣⁠נִי אֲלֵי⁠כֶ֑ם וְ⁠הָיָה֙ אִם־שָׁמ֣וֹעַ תִּשְׁמְע֔וּ⁠ן בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃ס","ẇ⁠rĕẖwòqi֣ym ׀ yábò֗ʼẇ ẇ⁠bánẇ֙ bĕ̇⁠héyka֣l yĕhwá֔h wi⁠ydaʻĕţė֕m kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֣⁠niy ʼàléy⁠ke֑m wĕ⁠háyáh֙ ʼim-şá̌m֣wòʻa ţi̇şĕ̌mĕʻ֔ẇ⁠n bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòhéy⁠keֽm׃s"],[7,1,"וַֽ⁠יְהִי֙ בִּ⁠שְׁנַ֣ת אַרְבַּ֔ע לְ⁠דָרְיָ֖וֶשׁ הַ⁠מֶּ֑לֶךְ הָיָ֨ה דְבַר־יְהוָ֜ה אֶל־זְכַרְיָ֗ה בְּ⁠אַרְבָּעָ֛ה לַ⁠חֹ֥דֶשׁ הַ⁠תְּשִׁעִ֖י בְּ⁠כִסְלֵֽו׃","waֽ⁠yĕhiy֙ bi̇⁠şĕ̌na֣ţ ʼarĕbȧ֔ʻ lĕ⁠dárĕyá֖weş̌ ha⁠mė֑lekĕ háyá֨h dĕbar-yĕhwá֜h ʼel-zĕkarĕyá֗h bĕ̇⁠ʼarĕbá̇ʻá֛h la⁠ẖò֥deş̌ ha⁠ţĕ̇şǐʻi֖y bĕ̇⁠kisĕléֽw׃"],[7,2,"וַ⁠יִּשְׁלַח֙ בֵּֽית־אֵ֔ל שַׂר־אֶ֕צֶר וְ⁠רֶ֥גֶם מֶ֖לֶךְ וַֽ⁠אֲנָשָׁ֑י⁠ו לְ⁠חַלּ֖וֹת אֶת־פְּנֵ֥י יְהוָֽה׃","wa⁠yi̇şĕ̌laẖ֙ béֽ̇yţ-ʼé֔l şâr-ʼe֕ẕer wĕ⁠re֥gem me֖lekĕ waֽ⁠ʼànáşá֑̌y⁠w lĕ⁠ẖal֖̇wòţ ʼeţ-pĕ̇né֥y yĕhwáֽh׃"],[7,3,"לֵ⁠אמֹ֗ר אֶל־הַ⁠כֹּֽהֲנִים֙ אֲשֶׁר֙ לְ⁠בֵית־יְהוָ֣ה צְבָא֔וֹת וְ⁠אֶל־הַ⁠נְּבִיאִ֖ים לֵ⁠אמֹ֑ר הַֽ⁠אֶבְכֶּה֙ בַּ⁠חֹ֣דֶשׁ הַ⁠חֲמִשִׁ֔י הִנָּזֵ֕ר כַּ⁠אֲשֶׁ֣ר עָשִׂ֔יתִי זֶ֖ה כַּ⁠מֶּ֥ה שָׁנִֽים׃פ","lé⁠ʼmò֗r ʼel-ha⁠kòֽ̇hàniym֙ ʼàşěr֙ lĕ⁠béyţ-yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠ʼel-ha⁠nĕ̇biyʼi֖ym lé⁠ʼmò֑r haֽ⁠ʼebĕkėh֙ bȧ⁠ẖò֣deş̌ ha⁠ẖàmişǐ֔y hiná̇zé֕r kȧ⁠ʼàşě֣r ʻáşî֔yţiy ze֖h kȧ⁠mė֥h şá̌niֽym׃p"],[7,4,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ ʼéla֥⁠y lé⁠ʼmòֽr׃"],[7,5,"אֱמֹר֙ אֶל־כָּל־עַ֣ם הָ⁠אָ֔רֶץ וְ⁠אֶל־הַ⁠כֹּהֲנִ֖ים לֵ⁠אמֹ֑ר כִּֽי־צַמְתֶּ֨ם וְ⁠סָפ֜וֹד בַּ⁠חֲמִישִׁ֣י וּ⁠בַ⁠שְּׁבִיעִ֗י וְ⁠זֶה֙ שִׁבְעִ֣ים שָׁנָ֔ה הֲ⁠צ֥וֹם צַמְתֻּ֖⁠נִי אָֽנִי׃","ʼèmòr֙ ʼel-ká̇l-ʻa֣m há⁠ʼá֔reẕ wĕ⁠ʼel-ha⁠kò̇hàni֖ym lé⁠ʼmò֑r kiֽ̇y-ẕamĕţė֨m wĕ⁠sáp֜wòd bȧ⁠ẖàmiyşǐ֣y ẇ⁠ba⁠şĕ̇̌biyʻi֗y wĕ⁠zeh֙ şǐbĕʻi֣ym şá̌ná֔h hà⁠ẕ֥wòm ẕamĕţu֖̇⁠niy ʼáֽniy׃"],[7,6,"וְ⁠כִ֥י תֹאכְל֖וּ וְ⁠כִ֣י תִשְׁתּ֑וּ הֲ⁠ל֤וֹא אַתֶּם֙ הָ⁠אֹ֣כְלִ֔ים וְ⁠אַתֶּ֖ם הַ⁠שֹּׁתִֽים׃","wĕ⁠ki֥y ţòʼkĕl֖ẇ wĕ⁠ki֣y ţişĕ̌ţ֑̇ẇ hà⁠l֤wòʼ ʼaţėm֙ há⁠ʼò֣kĕli֔ym wĕ⁠ʼaţė֖m ha⁠şò̇̌ţiֽym׃"],[7,7,"הֲ⁠ל֣וֹא אֶת־הַ⁠דְּבָרִ֗ים אֲשֶׁ֨ר קָרָ֤א יְהוָה֙ בְּ⁠יַד֙ הַ⁠נְּבִיאִ֣ים הָ⁠רִֽאשֹׁנִ֔ים בִּ⁠הְי֤וֹת יְרוּשָׁלִַ֨ם֙ יֹשֶׁ֣בֶת וּ⁠שְׁלֵוָ֔ה וְ⁠עָרֶ֖י⁠הָ סְבִיבֹתֶ֑י⁠הָ וְ⁠הַ⁠נֶּ֥גֶב וְ⁠הַ⁠שְּׁפֵלָ֖ה יֹשֵֽׁב׃פ","hà⁠l֣wòʼ ʼeţ-ha⁠dĕ̇bári֗ym ʼàşě֨r qárá֤ʼ yĕhwáh֙ bĕ̇⁠yad֙ ha⁠nĕ̇biyʼi֣ym há⁠riֽʼşò̌ni֔ym bi̇⁠hĕy֤wòţ yĕrẇşá̌lia֨m֙ yòşě֣beţ ẇ⁠şĕ̌léwá֔h wĕ⁠ʻáre֖y⁠há sĕbiybòţe֑y⁠há wĕ⁠ha⁠nė֥geb wĕ⁠ha⁠şĕ̇̌pélá֖h yòşéֽ̌b׃p"],[7,8,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־זְכַרְיָ֖ה לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-zĕkarĕyá֖h lé⁠ʼmòֽr׃"],[7,9,"כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר מִשְׁפַּ֤ט אֱמֶת֙ שְׁפֹ֔טוּ וְ⁠חֶ֣סֶד וְ⁠רַֽחֲמִ֔ים עֲשׂ֖וּ אִ֥ישׁ אֶת־אָחִֽי⁠ו׃","kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r mişĕ̌pȧ֤t ʼèmeţ֙ şĕ̌pò֔tẇ wĕ⁠ẖe֣sed wĕ⁠raֽẖàmi֔ym ʻàş֖̂ẇ ʼi֥yş̌ ʼeţ-ʼáẖiֽy⁠w׃"],[7,10,"וְ⁠אַלְמָנָ֧ה וְ⁠יָת֛וֹם גֵּ֥ר וְ⁠עָנִ֖י אַֽל־תַּעֲשֹׁ֑קוּ וְ⁠רָעַת֙ אִ֣ישׁ אָחִ֔י⁠ו אַֽל־תַּחְשְׁב֖וּ בִּ⁠לְבַבְ⁠כֶֽם׃","wĕ⁠ʼalĕmáná֧h wĕ⁠yáţ֛wòm gé֥̇r wĕ⁠ʻáni֖y ʼaֽl-ţȧʻàşò֑̌qẇ wĕ⁠ráʻaţ֙ ʼi֣yş̌ ʼáẖi֔y⁠w ʼaֽl-ţȧẖĕşĕ̌b֖ẇ bi̇⁠lĕbabĕ⁠keֽm׃"],[7,11,"וַ⁠יְמָאֲנ֣וּ לְ⁠הַקְשִׁ֔יב וַ⁠יִּתְּנ֥וּ כָתֵ֖ף סֹרָ֑רֶת וְ⁠אָזְנֵי⁠הֶ֖ם הִכְבִּ֥ידוּ מִ⁠שְּׁמֽוֹעַ׃","wa⁠yĕmáʼàn֣ẇ lĕ⁠haqĕşǐ֔yb wa⁠yi̇ţĕ̇n֥ẇ káţé֖p sòrá֑reţ wĕ⁠ʼázĕnéy⁠he֖m hikĕbi֥̇ydẇ mi⁠şĕ̇̌mֽwòʻa׃"],[7,12,"וְ⁠לִבָּ֞⁠ם שָׂ֣מוּ שָׁמִ֗יר מִ֠⁠שְּׁמוֹעַ אֶת־הַ⁠תּוֹרָ֤ה וְ⁠אֶת־הַ⁠דְּבָרִים֙ אֲשֶׁ֨ר שָׁלַ֜ח יְהוָ֤ה צְבָאוֹת֙ בְּ⁠רוּח֔⁠וֹ בְּ⁠יַ֖ד הַ⁠נְּבִיאִ֣ים הָ⁠רִֽאשֹׁנִ֑ים וַֽ⁠יְהִי֙ קֶ֣צֶף גָּד֔וֹל מֵ⁠אֵ֖ת יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠libá̇֞⁠m şá֣̂mẇ şá̌mi֗yr mi֠⁠şĕ̇̌mwòʻa ʼeţ-ha⁠ţ̇wòrá֤h wĕ⁠ʼeţ-ha⁠dĕ̇báriym֙ ʼàşě֨r şá̌la֜ẖ yĕhwá֤h ẕĕbáʼwòţ֙ bĕ̇⁠rẇẖ֔⁠wò bĕ̇⁠ya֖d ha⁠nĕ̇biyʼi֣ym há⁠riֽʼşò̌ni֑ym waֽ⁠yĕhiy֙ qe֣ẕep gá̇d֔wòl mé⁠ʼé֖ţ yĕhwá֥h ẕĕbáʼֽwòţ׃"],[7,13,"וַ⁠יְהִ֥י כַ⁠אֲשֶׁר־קָרָ֖א וְ⁠לֹ֣א שָׁמֵ֑עוּ כֵּ֤ן יִקְרְאוּ֙ וְ⁠לֹ֣א אֶשְׁמָ֔ע אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wa⁠yĕhi֥y ka⁠ʼàşěr-qárá֖ʼ wĕ⁠lò֣ʼ şá̌mé֑ʻẇ ké֤̇n yiqĕrĕʼẇ֙ wĕ⁠lò֣ʼ ʼeşĕ̌má֔ʻ ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[7,14,"וְ⁠אֵ֣סָעֲרֵ֗⁠ם עַ֤ל כָּל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר לֹֽא־יְדָע֔וּ⁠ם וְ⁠הָ⁠אָ֨רֶץ֙ נָשַׁ֣מָּה אַֽחֲרֵי⁠הֶ֔ם מֵֽ⁠עֹבֵ֖ר וּ⁠מִ⁠שָּׁ֑ב וַ⁠יָּשִׂ֥ימוּ אֶֽרֶץ־חֶמְדָּ֖ה לְ⁠שַׁמָּֽה׃פ","wĕ⁠ʼé֣sáʻàré֗⁠m ʻa֤l ká̇l-ha⁠ġwòyim֙ ʼàşě֣r lòֽʼ-yĕdáʻ֔ẇ⁠m wĕ⁠há⁠ʼá֨reẕ֙ náşǎ֣má̇h ʼaֽẖàréy⁠he֔m méֽ⁠ʻòbé֖r ẇ⁠mi⁠şá֑̇̌b wa⁠yá̇şî֥ymẇ ʼeֽreẕ-ẖemĕdá֖̇h lĕ⁠şǎmáֽ̇h׃p"],[8,1,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmòֽr׃"],[8,2,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת קִנֵּ֥אתִי לְ⁠צִיּ֖וֹן קִנְאָ֣ה גְדוֹלָ֑ה וְ⁠חֵמָ֥ה גְדוֹלָ֖ה קִנֵּ֥אתִי לָֽ⁠הּ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ qiné֥̇ʼţiy lĕ⁠ẕiẏ֖wòn qinĕʼá֣h gĕdwòlá֑h wĕ⁠ẖémá֥h gĕdwòlá֖h qiné֥̇ʼţiy láֽ⁠ḣ׃"],[8,3,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה שַׁ֚בְתִּי אֶל־צִיּ֔וֹן וְ⁠שָׁכַנְתִּ֖י בְּ⁠ת֣וֹךְ יְרֽוּשָׁלִָ֑ם וְ⁠נִקְרְאָ֤ה יְרוּשָׁלִַ֨ם֙ עִ֣יר־הָֽ⁠אֱמֶ֔ת וְ⁠הַר־יְהוָ֥ה צְבָא֖וֹת הַ֥ר הַ⁠קֹּֽדֶשׁ׃ס","kò֚̇h ʼáma֣r yĕhwá֔h şǎ֚bĕţi̇y ʼel-ẕiẏ֔wòn wĕ⁠şá̌kanĕţi֖̇y bĕ̇⁠ţ֣wòkĕ yĕrֽẇşá̌liá֑m wĕ⁠niqĕrĕʼá֤h yĕrẇşá̌lia֨m֙ ʻi֣yr-háֽ⁠ʼème֔ţ wĕ⁠har-yĕhwá֥h ẕĕbáʼ֖wòţ ha֥r ha⁠qòֽ̇deş̌׃s"],[8,4,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת עֹ֤ד יֵֽשְׁבוּ֙ זְקֵנִ֣ים וּ⁠זְקֵנ֔וֹת בִּ⁠רְחֹב֖וֹת יְרוּשָׁלִָ֑ם וְ⁠אִ֧ישׁ מִשְׁעַנְתּ֛⁠וֹ בְּ⁠יָד֖⁠וֹ מֵ⁠רֹ֥ב יָמִֽים׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻò֤d yéֽşĕ̌bẇ֙ zĕqéni֣ym ẇ⁠zĕqén֔wòţ bi̇⁠rĕẖòb֖wòţ yĕrẇşá̌liá֑m wĕ⁠ʼi֧yş̌ mişĕ̌ʻanĕţ֛̇⁠wò bĕ̇⁠yád֖⁠wò mé⁠rò֥b yámiֽym׃"],[8,5,"וּ⁠רְחֹב֤וֹת הָ⁠עִיר֙ יִמָּ֣לְא֔וּ יְלָדִ֖ים וִֽ⁠ילָד֑וֹת מְשַׂחֲקִ֖ים בִּ⁠רְחֹֽבֹתֶֽי⁠הָ׃ס","ẇ⁠rĕẖòb֤wòţ há⁠ʻiyr֙ yimá֣̇lĕʼ֔ẇ yĕládi֖ym wiֽ⁠ylád֑wòţ mĕşâẖàqi֖ym bi̇⁠rĕẖòֽbòţeֽy⁠há׃s"],[8,6,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת כִּ֣י יִפָּלֵ֗א בְּ⁠עֵינֵי֙ שְׁאֵרִית֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה בַּ⁠יָּמִ֖ים הָ⁠הֵ֑ם גַּם־בְּ⁠עֵינַ⁠י֙ יִפָּלֵ֔א נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃פ","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ki֣̇y yipá̇lé֗ʼ bĕ̇⁠ʻéynéy֙ şĕ̌ʼériyţ֙ há⁠ʻá֣m ha⁠zė֔h bȧ⁠yá̇mi֖ym há⁠hé֑m gȧm-bĕ̇⁠ʻéyna⁠y֙ yipá̇lé֔ʼ nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[8,7,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִ֥י מוֹשִׁ֛יעַ אֶת־עַמִּ֖⁠י מֵ⁠אֶ֣רֶץ מִזְרָ֑ח וּ⁠מֵ⁠אֶ֖רֶץ מְב֥וֹא הַ⁠שָּֽׁמֶשׁ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠ni֥y mwòşǐ֛yʻa ʼeţ-ʻami֖̇⁠y mé⁠ʼe֣reẕ mizĕrá֑ẖ ẇ⁠mé⁠ʼe֖reẕ mĕb֥wòʼ ha⁠şáֽ̇̌meş̌׃"],[8,8,"וְ⁠הֵבֵאתִ֣י אֹתָ֔⁠ם וְ⁠שָׁכְנ֖וּ בְּ⁠ת֣וֹךְ יְרוּשָׁלִָ֑ם וְ⁠הָיוּ־לִ֣⁠י לְ⁠עָ֗ם וַֽ⁠אֲנִי֙ אֶהְיֶ֤ה לָ⁠הֶם֙ לֵֽ⁠אלֹהִ֔ים בֶּ⁠אֱמֶ֖ת וּ⁠בִ⁠צְדָקָֽה׃ס","wĕ⁠hébéʼţi֣y ʼòţá֔⁠m wĕ⁠şá̌kĕn֖ẇ bĕ̇⁠ţ֣wòkĕ yĕrẇşá̌liá֑m wĕ⁠háyẇ-li֣⁠y lĕ⁠ʻá֗m waֽ⁠ʼàniy֙ ʼehĕye֤h lá⁠hem֙ léֽ⁠ʼlòhi֔ym bė⁠ʼème֖ţ ẇ⁠bi⁠ẕĕdáqáֽh׃s"],[8,9,"כֹּֽה־אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ תֶּחֱזַ֣קְנָה יְדֵי⁠כֶ֔ם הַ⁠שֹּֽׁמְעִים֙ בַּ⁠יָּמִ֣ים הָ⁠אֵ֔לֶּה אֵ֖ת הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה מִ⁠פִּי֙ הַ⁠נְּבִיאִ֔ים אֲ֠שֶׁר בְּ⁠י֞וֹם יֻסַּ֨ד בֵּית־יְהוָ֧ה צְבָא֛וֹת הַ⁠הֵיכָ֖ל לְ⁠הִבָּנֽוֹת׃","kòֽ̇h-ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ ţėẖèza֣qĕnáh yĕdéy⁠ke֔m ha⁠şòֽ̇̌mĕʻiym֙ bȧ⁠yá̇mi֣ym há⁠ʼé֔lėh ʼé֖ţ ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh mi⁠pi̇y֙ ha⁠nĕ̇biyʼi֔ym ʼà֠şěr bĕ̇⁠y֞wòm yusȧ֨d bé̇yţ-yĕhwá֧h ẕĕbáʼ֛wòţ ha⁠héyká֖l lĕ⁠hibá̇nֽwòţ׃"],[8,10,"כִּ֗י לִ⁠פְנֵי֙ הַ⁠יָּמִ֣ים הָ⁠הֵ֔ם שְׂכַ֤ר הָֽ⁠אָדָם֙ לֹ֣א נִֽהְיָ֔ה וּ⁠שְׂכַ֥ר הַ⁠בְּהֵמָ֖ה אֵינֶ֑⁠נָּה וְ⁠לַ⁠יּוֹצֵ֨א וְ⁠לַ⁠בָּ֤א אֵין־שָׁלוֹם֙ מִן־הַ⁠צָּ֔ר וַ⁠אֲשַׁלַּ֥ח אֶת־כָּל־הָ⁠אָדָ֖ם אִ֥ישׁ בְּ⁠רֵעֵֽ⁠הוּ׃","ki̇֗y li⁠pĕnéy֙ ha⁠yá̇mi֣ym há⁠hé֔m şĕ̂ka֤r háֽ⁠ʼádám֙ lò֣ʼ niֽhĕyá֔h ẇ⁠şĕ̂ka֥r ha⁠bĕ̇hémá֖h ʼéyne֑⁠ná̇h wĕ⁠la⁠ẏwòẕé֨ʼ wĕ⁠la⁠bá֤̇ʼ ʼéyn-şá̌lwòm֙ min-ha⁠ẕá̇֔r wa⁠ʼàşǎlȧ֥ẖ ʼeţ-ká̇l-há⁠ʼádá֖m ʼi֥yş̌ bĕ̇⁠réʻéֽ⁠hẇ׃"],[8,11,"וְ⁠עַתָּ֗ה לֹ֣א כַ⁠יָּמִ֤ים הָ⁠רִֽאשֹׁנִים֙ אֲנִ֔י לִ⁠שְׁאֵרִ֖ית הָ⁠עָ֣ם הַ⁠זֶּ֑ה נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʻaţá̇֗h lò֣ʼ ka⁠yá̇mi֤ym há⁠riֽʼşò̌niym֙ ʼàni֔y li⁠şĕ̌ʼéri֖yţ há⁠ʻá֣m ha⁠zė֑h nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[8,12,"כִּֽי־זֶ֣רַע הַ⁠שָּׁל֗וֹם הַ⁠גֶּ֜פֶן תִּתֵּ֤ן פִּרְיָ⁠הּ֙ וְ⁠הָ⁠אָ֨רֶץ֙ תִּתֵּ֣ן אֶת־יְבוּלָ֔⁠הּ וְ⁠הַ⁠שָּׁמַ֖יִם יִתְּנ֣וּ טַלָּ֑⁠ם וְ⁠הִנְחַלְתִּ֗י אֶת־שְׁאֵרִ֛ית הָ⁠עָ֥ם הַ⁠זֶּ֖ה אֶת־כָּל־אֵֽלֶּה׃","kiֽ̇y-ze֣raʻ ha⁠şá̇̌l֗wòm ha⁠gė֜pen ţi̇ţé֤̇n pi̇rĕyá⁠ḣ֙ wĕ⁠há⁠ʼá֨reẕ֙ ţi̇ţé֣̇n ʼeţ-yĕbẇlá֔⁠ḣ wĕ⁠ha⁠şá̇̌ma֖yim yiţĕ̇n֣ẇ talá֑̇⁠m wĕ⁠hinĕẖalĕţi̇֗y ʼeţ-şĕ̌ʼéri֛yţ há⁠ʻá֥m ha⁠zė֖h ʼeţ-ká̇l-ʼéֽlėh׃"],[8,13,"וְ⁠הָיָ֡ה כַּ⁠אֲשֶׁר֩ הֱיִיתֶ֨ם קְלָלָ֜ה בַּ⁠גּוֹיִ֗ם בֵּ֤ית יְהוּדָה֙ וּ⁠בֵ֣ית יִשְׂרָאֵ֔ל כֵּ֚ן אוֹשִׁ֣יעַ אֶתְ⁠כֶ֔ם וִ⁠הְיִיתֶ֖ם בְּרָכָ֑ה אַל־תִּירָ֖אוּ תֶּחֱזַ֥קְנָה יְדֵי⁠כֶֽם׃ס","wĕ⁠háyá֡h kȧ⁠ʼàşěr֩ hèyiyţe֨m qĕlálá֜h bȧ⁠ġwòyi֗m bé֤̇yţ yĕhẇdáh֙ ẇ⁠bé֣yţ yişĕ̂ráʼé֔l ké֚̇n ʼwòşǐ֣yʻa ʼeţĕ⁠ke֔m wi⁠hĕyiyţe֖m bĕ̇ráká֑h ʼal-ţi̇yrá֖ʼẇ ţėẖèza֥qĕnáh yĕdéy⁠keֽm׃s"],[8,14,"כִּ֣י כֹ֣ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ כַּ⁠אֲשֶׁ֨ר זָמַמְ֜תִּי לְ⁠הָרַ֣ע לָ⁠כֶ֗ם בְּ⁠הַקְצִ֤יף אֲבֹֽתֵי⁠כֶם֙ אֹתִ֔⁠י אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת וְ⁠לֹ֖א נִחָֽמְתִּי׃","ki֣̇y kò֣h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ kȧ⁠ʼàşě֨r zámamĕ֜ţi̇y lĕ⁠hára֣ʻ lá⁠ke֗m bĕ̇⁠haqĕẕi֤yp ʼàbòֽţéy⁠kem֙ ʼòţi֔⁠y ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠lò֖ʼ niẖáֽmĕţi̇y׃"],[8,15,"כֵּ֣ן שַׁ֤בְתִּי זָמַ֨מְתִּי֙ בַּ⁠יָּמִ֣ים הָ⁠אֵ֔לֶּה לְ⁠הֵיטִ֥יב אֶת־יְרוּשָׁלִַ֖ם וְ⁠אֶת־בֵּ֣ית יְהוּדָ֑ה אַל־תִּירָֽאוּ׃","ké֣̇n şǎ֤bĕţi̇y záma֨mĕţi̇y֙ bȧ⁠yá̇mi֣ym há⁠ʼé֔lėh lĕ⁠héyti֥yb ʼeţ-yĕrẇşá̌lia֖m wĕ⁠ʼeţ-bé֣̇yţ yĕhẇdá֑h ʼal-ţi̇yráֽʼẇ׃"],[8,16,"אֵ֥לֶּה הַ⁠דְּבָרִ֖ים אֲשֶׁ֣ר תַּֽעֲשׂ֑וּ דַּבְּר֤וּ אֱמֶת֙ אִ֣ישׁ אֶת־רֵעֵ֔⁠הוּ אֱמֶת֙ וּ⁠מִשְׁפַּ֣ט שָׁל֔וֹם שִׁפְט֖וּ בְּ⁠שַׁעֲרֵי⁠כֶֽם׃","ʼé֥lėh ha⁠dĕ̇bári֖ym ʼàşě֣r ţȧֽʻàş֑̂ẇ dȧbĕ̇r֤ẇ ʼèmeţ֙ ʼi֣yş̌ ʼeţ-réʻé֔⁠hẇ ʼèmeţ֙ ẇ⁠mişĕ̌pȧ֣t şá̌l֔wòm şǐpĕt֖ẇ bĕ̇⁠şǎʻàréy⁠keֽm׃"],[8,17,"וְ⁠אִ֣ישׁ ׀ אֶת־רָעַ֣ת רֵעֵ֗⁠הוּ אַֽל־תַּחְשְׁבוּ֙ בִּ⁠לְבַבְ⁠כֶ֔ם וּ⁠שְׁבֻ֥עַת שֶׁ֖קֶר אַֽל־תֶּאֱהָ֑בוּ כִּ֧י אֶת־כָּל־אֵ֛לֶּה אֲשֶׁ֥ר שָׂנֵ֖אתִי נְאֻם־יְהוָֽה׃ס","wĕ⁠ʼi֣yş̌ ׀ ʼeţ-ráʻa֣ţ réʻé֗⁠hẇ ʼaֽl-ţȧẖĕşĕ̌bẇ֙ bi̇⁠lĕbabĕ⁠ke֔m ẇ⁠şĕ̌bu֥ʻaţ şě֖qer ʼaֽl-ţėʼèhá֑bẇ ki֧̇y ʼeţ-ká̇l-ʼé֛lėh ʼàşě֥r şá̂né֖ʼţiy nĕʼum-yĕhwáֽh׃s"],[8,18,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ ʼéla֥⁠y lé⁠ʼmòֽr׃"],[8,19,"כֹּֽה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת צ֣וֹם הָ⁠רְבִיעִ֡י וְ⁠צ֣וֹם הַ⁠חֲמִישִׁי֩ וְ⁠צ֨וֹם הַ⁠שְּׁבִיעִ֜י וְ⁠צ֣וֹם הָ⁠עֲשִׂירִ֗י יִהְיֶ֤ה לְ⁠בֵית־יְהוּדָה֙ לְ⁠שָׂשׂ֣וֹן וּ⁠לְ⁠שִׂמְחָ֔ה וּֽ⁠לְ⁠מֹעֲדִ֖ים טוֹבִ֑ים וְ⁠הָ⁠אֱמֶ֥ת וְ⁠הַ⁠שָּׁל֖וֹם אֱהָֽבוּ׃פ","kòֽ̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ẕ֣wòm há⁠rĕbiyʻi֡y wĕ⁠ẕ֣wòm ha⁠ẖàmiyşǐy֩ wĕ⁠ẕ֨wòm ha⁠şĕ̇̌biyʻi֜y wĕ⁠ẕ֣wòm há⁠ʻàşîyri֗y yihĕye֤h lĕ⁠béyţ-yĕhẇdáh֙ lĕ⁠şá̂ş֣̂wòn ẇ⁠lĕ⁠şîmĕẖá֔h ẇֽ⁠lĕ⁠mòʻàdi֖ym twòbi֑ym wĕ⁠há⁠ʼème֥ţ wĕ⁠ha⁠şá̇̌l֖wòm ʼèháֽbẇ׃p"],[8,20,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת עֹ֚ד אֲשֶׁ֣ר יָבֹ֣אוּ עַמִּ֔ים וְ⁠יֹשְׁבֵ֖י עָרִ֥ים רַבּֽוֹת׃","kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ ʻò֚d ʼàşě֣r yábò֣ʼẇ ʻami̇֔ym wĕ⁠yòşĕ̌bé֖y ʻári֥ym raḃֽwòţ׃"],[8,21,"וְֽ⁠הָלְכ֡וּ יֹשְׁבֵי֩ אַחַ֨ת אֶל־אַחַ֜ת לֵ⁠אמֹ֗ר נֵלְכָ֤ה הָלוֹךְ֙ לְ⁠חַלּוֹת֙ אֶת־פְּנֵ֣י יְהוָ֔ה וּ⁠לְ⁠בַקֵּ֖שׁ אֶת־יְהוָ֣ה צְבָא֑וֹת אֵלְכָ֖ה גַּם־אָֽנִי׃","wĕֽ⁠hálĕk֡ẇ yòşĕ̌béy֩ ʼaẖa֨ţ ʼel-ʼaẖa֜ţ lé⁠ʼmò֗r nélĕká֤h hálwòkĕ֙ lĕ⁠ẖal̇wòţ֙ ʼeţ-pĕ̇né֣y yĕhwá֔h ẇ⁠lĕ⁠baqé֖̇ş̌ ʼeţ-yĕhwá֣h ẕĕbáʼ֑wòţ ʼélĕká֖h gȧm-ʼáֽniy׃"],[8,22,"וּ⁠בָ֨אוּ עַמִּ֤ים רַבִּים֙ וְ⁠גוֹיִ֣ם עֲצוּמִ֔ים לְ⁠בַקֵּ֛שׁ אֶת־יְהוָ֥ה צְבָא֖וֹת בִּ⁠ירוּשָׁלִָ֑ם וּ⁠לְ⁠חַלּ֖וֹת אֶת־פְּנֵ֥י יְהוָֽה׃ס","ẇ⁠bá֨ʼẇ ʻami֤̇ym rabi̇ym֙ wĕ⁠gwòyi֣m ʻàẕẇmi֔ym lĕ⁠baqé֛̇ş̌ ʼeţ-yĕhwá֥h ẕĕbáʼ֖wòţ bi̇⁠yrẇşá̌liá֑m ẇ⁠lĕ⁠ẖal֖̇wòţ ʼeţ-pĕ̇né֥y yĕhwáֽh׃s"],[8,23,"כֹּ֥ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ בַּ⁠יָּמִ֣ים הָ⁠הֵ֔מָּה אֲשֶׁ֤ר יַחֲזִ֨יקוּ֙ עֲשָׂרָ֣ה אֲנָשִׁ֔ים מִ⁠כֹּ֖ל לְשֹׁנ֣וֹת הַ⁠גּוֹיִ֑ם וְֽ⁠הֶחֱזִ֡יקוּ בִּ⁠כְנַף֩ אִ֨ישׁ יְהוּדִ֜י לֵ⁠אמֹ֗ר נֵֽלְכָה֙ עִמָּ⁠כֶ֔ם כִּ֥י שָׁמַ֖עְנוּ אֱלֹהִ֥ים עִמָּ⁠כֶֽם׃ס","kò֥̇h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ bȧ⁠yá̇mi֣ym há⁠hé֔má̇h ʼàşě֤r yaẖàzi֨yqẇ֙ ʻàşá̂rá֣h ʼànáşǐ֔ym mi⁠kò֖̇l lĕşò̌n֣wòţ ha⁠ġwòyi֑m wĕֽ⁠heẖèzi֡yqẇ bi̇⁠kĕnap֩ ʼi֨yş̌ yĕhẇdi֜y lé⁠ʼmò֗r néֽlĕkáh֙ ʻimá̇⁠ke֔m ki֥̇y şá̌ma֖ʻĕnẇ ʼèlòhi֥ym ʻimá̇⁠keֽm׃s"],[9,1,"מַשָּׂ֤א דְבַר־יְהוָה֙ בְּ⁠אֶ֣רֶץ חַדְרָ֔ךְ וְ⁠דַמֶּ֖שֶׂק מְנֻחָת֑⁠וֹ כִּ֤י לַֽ⁠יהוָה֙ עֵ֣ין אָדָ֔ם וְ⁠כֹ֖ל שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","maşá֤̇̂ʼ dĕbar-yĕhwáh֙ bĕ̇⁠ʼe֣reẕ ẖadĕrá֔kĕ wĕ⁠damė֖şêq mĕnuẖáţ֑⁠wò ki֤̇y laֽ⁠yhwáh֙ ʻé֣yn ʼádá֔m wĕ⁠kò֖l şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[9,2,"וְ⁠גַם־חֲמָ֖ת תִּגְבָּל־בָּ֑⁠הּ צֹ֣ר וְ⁠צִיד֔וֹן כִּ֥י חָֽכְמָ֖ה מְאֹֽד׃","wĕ⁠gam-ẖàmá֖ţ ţi̇gĕbá̇l-bá֑̇⁠ḣ ẕò֣r wĕ⁠ẕiyd֔wòn ki֥̇y ẖáֽkĕmá֖h mĕʼòֽd׃"],[9,3,"וַ⁠תִּ֥בֶן צֹ֛ר מָצ֖וֹר לָ֑⁠הּ וַ⁠תִּצְבָּר־כֶּ֨סֶף֙ כֶּֽ⁠עָפָ֔ר וְ⁠חָר֖וּץ כְּ⁠טִ֥יט חוּצֽוֹת׃","wa⁠ţi֥̇ben ẕò֛r máẕ֖wòr lá֑⁠ḣ wa⁠ţi̇ẕĕbá̇r-kė֨sep֙ kėֽ⁠ʻápá֔r wĕ⁠ẖár֖ẇẕ kĕ̇⁠ti֥yt ẖẇẕֽwòţ׃"],[9,4,"הִנֵּ֤ה אֲדֹנָ⁠י֙ יֽוֹרִשֶׁ֔⁠נָּה וְ⁠הִכָּ֥ה בַ⁠יָּ֖ם חֵילָ֑⁠הּ וְ⁠הִ֖יא בָּ⁠אֵ֥שׁ תֵּאָכֵֽל׃","hiné֤̇h ʼàdòná⁠y֙ yֽwòrişě֔⁠ná̇h wĕ⁠hiká֥̇h ba⁠yá֖̇m ẖéylá֑⁠ḣ wĕ⁠hi֖yʼ bá̇⁠ʼé֥ş̌ ţé̇ʼákéֽl׃"],[9,5,"תֵּרֶ֨א אַשְׁקְל֜וֹן וְ⁠תִירָ֗א וְ⁠עַזָּה֙ וְ⁠תָחִ֣יל מְאֹ֔ד וְ⁠עֶקְר֖וֹן כִּֽי־הֹבִ֣ישׁ מֶבָּטָ֑⁠הּ וְ⁠אָ֤בַד מֶ֨לֶךְ֙ מֵֽ⁠עַזָּ֔ה וְ⁠אַשְׁקְל֖וֹן לֹ֥א תֵשֵֽׁב׃","ţé̇re֨ʼ ʼaşĕ̌qĕl֜wòn wĕ⁠ţiyrá֗ʼ wĕ⁠ʻazá̇h֙ wĕ⁠ţáẖi֣yl mĕʼò֔d wĕ⁠ʻeqĕr֖wòn kiֽ̇y-hòbi֣yş̌ mebá̇tá֑⁠ḣ wĕ⁠ʼá֤bad me֨lekĕ֙ méֽ⁠ʻazá̇֔h wĕ⁠ʼaşĕ̌qĕl֖wòn lò֥ʼ ţéşéֽ̌b׃"],[9,6,"וְ⁠יָשַׁ֥ב מַמְזֵ֖ר בְּ⁠אַשְׁדּ֑וֹד וְ⁠הִכְרַתִּ֖י גְּא֥וֹן פְּלִשְׁתִּֽים׃","wĕ⁠yáşǎ֥b mamĕzé֖r bĕ̇⁠ʼaşĕ̌ḋ֑wòd wĕ⁠hikĕraţi֖̇y gĕ̇ʼ֥wòn pĕ̇lişĕ̌ţiֽ̇ym׃"],[9,7,"וַ⁠הֲסִרֹתִ֨י דָמָ֜י⁠ו מִ⁠פִּ֗י⁠ו וְ⁠שִׁקֻּצָי⁠ו֙ מִ⁠בֵּ֣ין שִׁנָּ֔י⁠ו וְ⁠נִשְׁאַ֥ר גַּם־ה֖וּא לֵֽ⁠אלֹהֵ֑י⁠נוּ וְ⁠הָיָה֙ כְּ⁠אַלֻּ֣ף בִּֽ⁠יהוּדָ֔ה וְ⁠עֶקְר֖וֹן כִּ⁠יבוּסִֽי׃","wa⁠hàsiròţi֨y dámá֜y⁠w mi⁠pi̇֗y⁠w wĕ⁠şǐqu̇ẕáy⁠w֙ mi⁠bé֣̇yn şǐná̇֔y⁠w wĕ⁠nişĕ̌ʼa֥r gȧm-h֖ẇʼ léֽ⁠ʼlòhé֑y⁠nẇ wĕ⁠háyáh֙ kĕ̇⁠ʼalu֣̇p biֽ̇⁠yhẇdá֔h wĕ⁠ʻeqĕr֖wòn ki̇⁠ybẇsiֽy׃"],[9,8,"וְ⁠חָנִ֨יתִי לְ⁠בֵיתִ֤⁠י מִצָּבָה֙ מֵ⁠עֹבֵ֣ר וּ⁠מִ⁠שָּׁ֔ב וְ⁠לֹֽא־יַעֲבֹ֧ר עֲלֵי⁠הֶ֛ם ע֖וֹד נֹגֵ֑שׂ כִּ֥י עַתָּ֖ה רָאִ֥יתִי בְ⁠עֵינָֽ⁠י׃ס","wĕ⁠ẖáni֨yţiy lĕ⁠béyţi֤⁠y miẕá̇báh֙ mé⁠ʻòbé֣r ẇ⁠mi⁠şá̇̌֔b wĕ⁠lòֽʼ-yaʻàbò֧r ʻàléy⁠he֛m ʻ֖wòd nògé֑ş̂ ki֥̇y ʻaţá֖̇h ráʼi֥yţiy bĕ⁠ʻéynáֽ⁠y׃s"],[9,9,"גִּילִ֨י מְאֹ֜ד בַּת־צִיּ֗וֹן הָרִ֨יעִי֙ בַּ֣ת יְרוּשָׁלִַ֔ם הִנֵּ֤ה מַלְכֵּ⁠ךְ֙ יָ֣בוֹא לָ֔⁠ךְ צַדִּ֥יק וְ⁠נוֹשָׁ֖ע ה֑וּא עָנִי֙ וְ⁠רֹכֵ֣ב עַל־חֲמ֔וֹר וְ⁠עַל־עַ֖יִר בֶּן־אֲתֹנֽוֹת׃","gi̇yli֨y mĕʼò֜d bȧţ-ẕiẏ֗wòn hári֨yʻiy֙ bȧ֣ţ yĕrẇşá̌lia֔m hiné֤̇h malĕké̇⁠kĕ֙ yá֣bwòʼ lá֔⁠kĕ ẕadi֥̇yq wĕ⁠nwòşá֖̌ʻ h֑ẇʼ ʻániy֙ wĕ⁠ròké֣b ʻal-ẖàm֔wòr wĕ⁠ʻal-ʻa֖yir bėn-ʼàţònֽwòţ׃"],[9,10,"וְ⁠הִכְרַתִּי־רֶ֣כֶב מֵ⁠אֶפְרַ֗יִם וְ⁠סוּס֙ מִ⁠יר֣וּשָׁלִַ֔ם וְ⁠נִכְרְתָה֙ קֶ֣שֶׁת מִלְחָמָ֔ה וְ⁠דִבֶּ֥ר שָׁל֖וֹם לַ⁠גּוֹיִ֑ם וּ⁠מָשְׁל⁠וֹ֙ מִ⁠יָּ֣ם עַד־יָ֔ם וּ⁠מִ⁠נָּהָ֖ר עַד־אַפְסֵי־אָֽרֶץ׃","wĕ⁠hikĕraţi̇y-re֣keb mé⁠ʼepĕra֗yim wĕ⁠sẇs֙ mi⁠yr֣ẇşá̌lia֔m wĕ⁠nikĕrĕţáh֙ qe֣şěţ milĕẖámá֔h wĕ⁠dibė֥r şá̌l֖wòm la⁠ġwòyi֑m ẇ⁠máşĕ̌l⁠wò֙ mi⁠yá֣̇m ʻad-yá֔m ẇ⁠mi⁠ná̇há֖r ʻad-ʼapĕséy-ʼáֽreẕ׃"],[9,11,"גַּם־אַ֣תְּ בְּ⁠דַם־בְּרִיתֵ֗⁠ךְ שִׁלַּ֤חְתִּי אֲסִירַ֨יִ⁠ךְ֙ מִ⁠בּ֔וֹר אֵ֥ין מַ֖יִם בּֽ⁠וֹ׃","gȧm-ʼa֣ţĕ̇ bĕ̇⁠dam-bĕ̇riyţé֗⁠kĕ şǐlȧ֤ẖĕţi̇y ʼàsiyra֨yi⁠kĕ֙ mi⁠ḃ֔wòr ʼé֥yn ma֖yim ḃֽ⁠wò׃"],[9,12,"שׁ֚וּבוּ לְ⁠בִצָּר֔וֹן אֲסִירֵ֖י הַ⁠תִּקְוָ֑ה גַּם־הַ⁠יּ֕וֹם מַגִּ֥יד מִשְׁנֶ֖ה אָשִׁ֥יב לָֽ⁠ךְ׃","ş֚̌ẇbẇ lĕ⁠biẕá̇r֔wòn ʼàsiyré֖y ha⁠ţi̇qĕwá֑h gȧm-ha⁠ẏ֕wòm magi֥̇yd mişĕ̌ne֖h ʼáşǐ֥yb láֽ⁠kĕ׃"],[9,13,"כִּֽי־דָרַ֨כְתִּי לִ֜⁠י יְהוּדָ֗ה קֶ֚שֶׁת מִלֵּ֣אתִי אֶפְרַ֔יִם וְ⁠עוֹרַרְתִּ֤י בָנַ֨יִ⁠ךְ֙ צִיּ֔וֹן עַל־בָּנַ֖יִ⁠ךְ יָוָ֑ן וְ⁠שַׂמְתִּ֖י⁠ךְ כְּ⁠חֶ֥רֶב גִּבּֽוֹר׃","kiֽ̇y-dára֨kĕţi̇y li֜⁠y yĕhẇdá֗h qe֚şěţ milé֣̇ʼţiy ʼepĕra֔yim wĕ⁠ʻwòrarĕţi֤̇y bána֨yi⁠kĕ֙ ẕiẏ֔wòn ʻal-bá̇na֖yi⁠kĕ yáwá֑n wĕ⁠şâmĕţi֖̇y⁠kĕ kĕ̇⁠ẖe֥reb gi̇ḃֽwòr׃"],[9,14,"וַֽ⁠יהוָה֙ עֲלֵי⁠הֶ֣ם יֵֽרָאֶ֔ה וְ⁠יָצָ֥א כַ⁠בָּרָ֖ק חִצּ֑⁠וֹ וַֽ⁠אדֹנָ֤⁠י יְהֹוִה֙ בַּ⁠שּׁוֹפָ֣ר יִתְקָ֔ע וְ⁠הָלַ֖ךְ בְּ⁠סַעֲר֥וֹת תֵּימָֽן׃","waֽ⁠yhwáh֙ ʻàléy⁠he֣m yéֽráʼe֔h wĕ⁠yáẕá֥ʼ ka⁠bá̇rá֖q ẖiẕ֑̇⁠wò waֽ⁠ʼdòná֤⁠y yĕhòwih֙ bȧ⁠ş̇̌wòpá֣r yiţĕqá֔ʻ wĕ⁠hála֖kĕ bĕ̇⁠saʻàr֥wòţ ţé̇ymáֽn׃"],[9,15,"יְהוָ֣ה צְבָאוֹת֮ יָגֵ֣ן עֲלֵי⁠הֶם֒ וְ⁠אָכְל֗וּ וְ⁠כָֽבְשׁוּ֙ אַבְנֵי־קֶ֔לַע וְ⁠שָׁת֥וּ הָמ֖וּ כְּמוֹ־יָ֑יִן וּ⁠מָֽלְאוּ֙ כַּ⁠מִּזְרָ֔ק כְּ⁠זָוִיּ֖וֹת מִזְבֵּֽחַ׃","yĕhwá֣h ẕĕbáʼwòţ֮ yágé֣n ʻàléy⁠hem֒ wĕ⁠ʼákĕl֗ẇ wĕ⁠káֽbĕş̌ẇ֙ ʼabĕnéy-qe֔laʻ wĕ⁠şá̌ţ֥ẇ hám֖ẇ kĕ̇mwò-yá֑yin ẇ⁠máֽlĕʼẇ֙ kȧ⁠mi̇zĕrá֔q kĕ̇⁠záwiẏ֖wòţ mizĕbéֽ̇ẖa׃"],[9,16,"וְֽ⁠הוֹשִׁיעָ֞⁠ם יְהוָ֧ה אֱלֹהֵי⁠הֶ֛ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כְּ⁠צֹ֣אן עַמּ֑⁠וֹ כִּ֚י אַבְנֵי־נֵ֔זֶר מִֽתְנוֹסְס֖וֹת עַל־אַדְמָתֽ⁠וֹ׃","wĕֽ⁠hwòşǐyʻá֞⁠m yĕhwá֧h ʼèlòhéy⁠he֛m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kĕ̇⁠ẕò֣ʼn ʻaṁ֑⁠wò ki֚̇y ʼabĕnéy-né֔zer miֽţĕnwòsĕs֖wòţ ʻal-ʼadĕmáţֽ⁠wò׃"],[9,17,"כִּ֥י מַה־טּוּב֖⁠וֹ וּ⁠מַה־יָפְי֑⁠וֹ דָּגָן֙ בַּֽחוּרִ֔ים וְ⁠תִיר֖וֹשׁ יְנוֹבֵ֥ב בְּתֻלֽוֹת׃","ki֥̇y mah-ṫẇb֖⁠wò ẇ⁠mah-yápĕy֑⁠wò dá̇gán֙ bȧֽẖẇri֔ym wĕ⁠ţiyr֖wòş̌ yĕnwòbé֥b bĕ̇ţulֽwòţ׃"],[10,1,"שַׁאֲל֨וּ מֵ⁠יְהוָ֤ה מָטָר֙ בְּ⁠עֵ֣ת מַלְק֔וֹשׁ יְהוָ֖ה עֹשֶׂ֣ה חֲזִיזִ֑ים וּ⁠מְטַר־גֶּ֨שֶׁם֙ יִתֵּ֣ן לָ⁠הֶ֔ם לְ⁠אִ֖ישׁ עֵ֥שֶׂב בַּ⁠שָּׂדֶֽה׃","şǎʼàl֨ẇ mé⁠yĕhwá֤h mátár֙ bĕ̇⁠ʻé֣ţ malĕq֔wòş̌ yĕhwá֖h ʻòşê֣h ẖàziyzi֑ym ẇ⁠mĕtar-gė֨şěm֙ yiţé֣̇n lá⁠he֔m lĕ⁠ʼi֖yş̌ ʻé֥şêb bȧ⁠şá̇̂deֽh׃"],[10,2,"כִּ֧י הַ⁠תְּרָפִ֣ים דִּבְּרוּ־אָ֗וֶן וְ⁠הַ⁠קּֽוֹסְמִים֙ חָ֣זוּ שֶׁ֔קֶר וַֽ⁠חֲלֹמוֹת֙ הַ⁠שָּׁ֣וא יְדַבֵּ֔רוּ הֶ֖בֶל יְנַֽחֵמ֑וּ⁠ן עַל־כֵּן֙ נָסְע֣וּ כְמוֹ־צֹ֔אן יַעֲנ֖וּ כִּֽי־אֵ֥ין רֹעֶֽה׃פ","ki֧̇y ha⁠ţĕ̇rápi֣ym di̇bĕ̇rẇ-ʼá֗wen wĕ⁠ha⁠qֽ̇wòsĕmiym֙ ẖá֣zẇ şě֔qer waֽ⁠ẖàlòmwòţ֙ ha⁠şá֣̇̌wʼ yĕdabé̇֔rẇ he֖bel yĕnaֽẖém֑ẇ⁠n ʻal-ké̇n֙ násĕʻ֣ẇ kĕmwò-ẕò֔ʼn yaʻàn֖ẇ kiֽ̇y-ʼé֥yn ròʻeֽh׃p"],[10,3,"עַל־הָֽ⁠רֹעִים֙ חָרָ֣ה אַפִּ֔⁠י וְ⁠עַל־הָ⁠עַתּוּדִ֖ים אֶפְק֑וֹד כִּֽי־פָקַד֩ יְהוָ֨ה צְבָא֤וֹת אֶת־עֶדְר⁠וֹ֙ אֶת־בֵּ֣ית יְהוּדָ֔ה וְ⁠שָׂ֣ם אוֹתָ֔⁠ם כְּ⁠ס֥וּס הוֹד֖⁠וֹ בַּ⁠מִּלְחָמָֽה׃","ʻal-háֽ⁠ròʻiym֙ ẖárá֣h ʼapi̇֔⁠y wĕ⁠ʻal-há⁠ʻaţ̇ẇdi֖ym ʼepĕq֑wòd kiֽ̇y-páqad֩ yĕhwá֨h ẕĕbáʼ֤wòţ ʼeţ-ʻedĕr⁠wò֙ ʼeţ-bé֣̇yţ yĕhẇdá֔h wĕ⁠şá֣̂m ʼwòţá֔⁠m kĕ̇⁠s֥ẇs hwòd֖⁠wò bȧ⁠mi̇lĕẖámáֽh׃"],[10,4,"מִמֶּ֤⁠נּוּ פִנָּה֙ מִמֶּ֣⁠נּוּ יָתֵ֔ד מִמֶּ֖⁠נּוּ קֶ֣שֶׁת מִלְחָמָ֑ה מִמֶּ֛⁠נּוּ יֵצֵ֥א כָל־נוֹגֵ֖שׂ יַחְדָּֽו׃","mimė֤⁠ṅẇ piná̇h֙ mimė֣⁠ṅẇ yáţé֔d mimė֖⁠ṅẇ qe֣şěţ milĕẖámá֑h mimė֛⁠ṅẇ yéẕé֥ʼ kál-nwògé֖ş̂ yaẖĕdáֽ̇w׃"],[10,5,"וְ⁠הָי֨וּ כְ⁠גִבֹּרִ֜ים בּוֹסִ֨ים בְּ⁠טִ֤יט חוּצוֹת֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠נִ֨לְחֲמ֔וּ כִּ֥י יְהוָ֖ה עִמָּ֑⁠ם וְ⁠הֹבִ֖ישׁוּ רֹכְבֵ֥י סוּסִֽים׃","wĕ⁠háy֨ẇ kĕ⁠gibò̇ri֜ym ḃwòsi֨ym bĕ̇⁠ti֤yt ẖẇẕwòţ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠ni֨lĕẖàm֔ẇ ki֥̇y yĕhwá֖h ʻimá֑̇⁠m wĕ⁠hòbi֖yş̌ẇ ròkĕbé֥y sẇsiֽym׃"],[10,6,"וְ⁠גִבַּרְתִּ֣י ׀ אֶת־בֵּ֣ית יְהוּדָ֗ה וְ⁠אֶת־בֵּ֤ית יוֹסֵף֙ אוֹשִׁ֔יעַ וְ⁠הֽוֹשְׁבוֹתִי⁠ם֙ כִּ֣י רִֽחַמְתִּ֔י⁠ם וְ⁠הָי֖וּ כַּ⁠אֲשֶׁ֣ר לֹֽא־זְנַחְתִּ֑י⁠ם כִּ֗י אֲנִ֛י יְהוָ֥ה אֱלֹהֵי⁠הֶ֖ם וְ⁠אֶעֱנֵֽ⁠ם׃","wĕ⁠gibȧrĕţi֣̇y ׀ ʼeţ-bé֣̇yţ yĕhẇdá֗h wĕ⁠ʼeţ-bé֤̇yţ ywòsép֙ ʼwòşǐ֔yʻa wĕ⁠hֽwòşĕ̌bwòţiy⁠m֙ ki֣̇y riֽẖamĕţi̇֔y⁠m wĕ⁠háy֖ẇ kȧ⁠ʼàşě֣r lòֽʼ-zĕnaẖĕţi֑̇y⁠m ki̇֗y ʼàni֛y yĕhwá֥h ʼèlòhéy⁠he֖m wĕ⁠ʼeʻènéֽ⁠m׃"],[10,7,"וְ⁠הָי֤וּ כְ⁠גִבּוֹר֙ אֶפְרַ֔יִם וְ⁠שָׂמַ֥ח לִבָּ֖⁠ם כְּמוֹ־יָ֑יִן וּ⁠בְנֵי⁠הֶם֙ יִרְא֣וּ וְ⁠שָׂמֵ֔חוּ יָגֵ֥ל לִבָּ֖⁠ם בַּ⁠יהוָֽה׃","wĕ⁠háy֤ẇ kĕ⁠giḃwòr֙ ʼepĕra֔yim wĕ⁠şá̂ma֥ẖ libá֖̇⁠m kĕ̇mwò-yá֑yin ẇ⁠bĕnéy⁠hem֙ yirĕʼ֣ẇ wĕ⁠şá̂mé֔ẖẇ yágé֥l libá֖̇⁠m bȧ⁠yhwáֽh׃"],[10,8,"אֶשְׁרְקָ֥ה לָ⁠הֶ֛ם וַ⁠אֲקַבְּצֵ֖⁠ם כִּ֣י פְדִיתִ֑י⁠ם וְ⁠רָב֖וּ כְּמ֥וֹ רָבֽוּ׃","ʼeşĕ̌rĕqá֥h lá⁠he֛m wa⁠ʼàqabĕ̇ẕé֖⁠m ki֣̇y pĕdiyţi֑y⁠m wĕ⁠ráb֖ẇ kĕ̇m֥wò rábֽẇ׃"],[10,9,"וְ⁠אֶזְרָעֵ⁠ם֙ בָּֽ⁠עַמִּ֔ים וּ⁠בַ⁠מֶּרְחַקִּ֖ים יִזְכְּר֑וּ⁠נִי וְ⁠חָי֥וּ אֶת־בְּנֵי⁠הֶ֖ם וָ⁠שָֽׁבוּ׃","wĕ⁠ʼezĕráʻé⁠m֙ báֽ̇⁠ʻami̇֔ym ẇ⁠ba⁠mėrĕẖaqi֖̇ym yizĕkĕ̇r֑ẇ⁠niy wĕ⁠ẖáy֥ẇ ʼeţ-bĕ̇néy⁠he֖m wá⁠şáֽ̌bẇ׃"],[10,10,"וַ⁠הֲשִֽׁיבוֹתִי⁠ם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם וּ⁠מֵֽ⁠אַשּׁ֖וּר אֲקַבְּצֵ֑⁠ם וְ⁠אֶל־אֶ֨רֶץ גִּלְעָ֤ד וּ⁠לְבָנוֹן֙ אֲבִיאֵ֔⁠ם וְ⁠לֹ֥א יִמָּצֵ֖א לָ⁠הֶֽם׃","wa⁠hàşǐֽybwòţiy⁠m֙ mé⁠ʼe֣reẕ miẕĕra֔yim ẇ⁠méֽ⁠ʼaş֖̇̌ẇr ʼàqabĕ̇ẕé֑⁠m wĕ⁠ʼel-ʼe֨reẕ gi̇lĕʻá֤d ẇ⁠lĕbánwòn֙ ʼàbiyʼé֔⁠m wĕ⁠lò֥ʼ yimá̇ẕé֖ʼ lá⁠heֽm׃"],[10,11,"וְ⁠עָבַ֨ר בַּ⁠יָּ֜ם צָרָ֗ה וְ⁠הִכָּ֤ה בַ⁠יָּם֙ גַּלִּ֔ים וְ⁠הֹבִ֕ישׁוּ כֹּ֖ל מְצוּל֣וֹת יְאֹ֑ר וְ⁠הוּרַד֙ גְּא֣וֹן אַשּׁ֔וּר וְ⁠שֵׁ֥בֶט מִצְרַ֖יִם יָסֽוּר׃","wĕ⁠ʻába֨r bȧ⁠yá̇֜m ẕárá֗h wĕ⁠hiká֤̇h ba⁠yá̇m֙ gȧli̇֔ym wĕ⁠hòbi֕yş̌ẇ kò֖̇l mĕẕẇl֣wòţ yĕʼò֑r wĕ⁠hẇrad֙ gĕ̇ʼ֣wòn ʼaş̇̌֔ẇr wĕ⁠şé֥̌bet miẕĕra֖yim yásֽẇr׃"],[10,12,"וְ⁠גִבַּרְתִּי⁠ם֙ בַּֽ⁠יהוָ֔ה וּ⁠בִ⁠שְׁמ֖⁠וֹ יִתְהַלָּ֑כוּ נְאֻ֖ם יְהוָֽה׃ס","wĕ⁠gibȧrĕţi̇y⁠m֙ bȧֽ⁠yhwá֔h ẇ⁠bi⁠şĕ̌m֖⁠wò yiţĕhalá֑̇kẇ nĕʼu֖m yĕhwáֽh׃s"],[11,1,"פְּתַ֥ח לְבָנ֖וֹן דְּלָתֶ֑י⁠ךָ וְ⁠תֹאכַ֥ל אֵ֖שׁ בַּ⁠אֲרָזֶֽי⁠ךָ׃","pĕ̇ţa֥ẖ lĕbán֖wòn dĕ̇láţe֑y⁠ká wĕ⁠ţòʼka֥l ʼé֖ş̌ bȧ⁠ʼàrázeֽy⁠ká׃"],[11,2,"הֵילֵ֤ל בְּרוֹשׁ֙ כִּֽי־נָ֣פַל אֶ֔רֶז אֲשֶׁ֥ר אַדִּרִ֖ים שֻׁדָּ֑דוּ הֵילִ֨ילוּ֙ אַלּוֹנֵ֣י בָשָׁ֔ן כִּ֥י יָרַ֖ד יַ֥עַר ה⁠בצור׃","héylé֤l bĕ̇rwòş̌֙ kiֽ̇y-ná֣pal ʼe֔rez ʼàşě֥r ʼadi̇ri֖ym şǔdá֑̇dẇ héyli֨ylẇ֙ ʼal̇wòné֣y báşá̌֔n ki֥̇y yára֖d ya֥ʻar h⁠bẕwr׃"],[11,3,"ק֚וֹל יִֽלְלַ֣ת הָ⁠רֹעִ֔ים כִּ֥י שֻׁדְּדָ֖ה אַדַּרְתָּ֑⁠ם ק֚וֹל שַׁאֲגַ֣ת כְּפִירִ֔ים כִּ֥י שֻׁדַּ֖ד גְּא֥וֹן הַ⁠יַּרְדֵּֽן׃ס","q֚wòl yiֽlĕla֣ţ há⁠ròʻi֔ym ki֥̇y şǔdĕ̇dá֖h ʼadȧrĕţá֑̇⁠m q֚wòl şǎʼàga֣ţ kĕ̇piyri֔ym ki֥̇y şǔdȧ֖d gĕ̇ʼ֥wòn ha⁠yȧrĕdéֽ̇n׃s"],[11,4,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה אֱלֹהָ֑⁠י רְעֵ֖ה אֶת־צֹ֥אן הַ⁠הֲרֵגָֽה׃","kò֥̇h ʼáma֖r yĕhwá֣h ʼèlòhá֑⁠y rĕʻé֖h ʼeţ-ẕò֥ʼn ha⁠hàrégáֽh׃"],[11,5,"אֲשֶׁ֨ר קֹנֵי⁠הֶ֤ן יַֽהֲרְגֻ⁠ן֙ וְ⁠לֹ֣א יֶאְשָׁ֔מוּ וּ⁠מֹכְרֵי⁠הֶ֣ן יֹאמַ֔ר בָּר֥וּךְ יְהוָ֖ה וַ⁠אעְשִׁ֑ר וְ⁠רֹ֣עֵי⁠הֶ֔ם לֹ֥א יַחְמ֖וֹל עֲלֵי⁠הֶֽן׃","ʼàşě֨r qònéy⁠he֤n yaֽhàrĕgu⁠n֙ wĕ⁠lò֣ʼ yeʼĕşá̌֔mẇ ẇ⁠mòkĕréy⁠he֣n yòʼma֔r bá̇r֥ẇkĕ yĕhwá֖h wa⁠ʼʻĕşǐ֑r wĕ⁠rò֣ʻéy⁠he֔m lò֥ʼ yaẖĕm֖wòl ʻàléy⁠heֽn׃"],[11,6,"כִּ֠י לֹ֣א אֶחְמ֥וֹל ע֛וֹד עַל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ נְאֻם־יְהוָ֑ה וְ⁠הִנֵּ֨ה אָנֹכִ֜י מַמְצִ֣יא אֶת־הָ⁠אָדָ֗ם אִ֤ישׁ בְּ⁠יַד־רֵעֵ֨⁠הוּ֙ וּ⁠בְ⁠יַ֣ד מַלְכּ֔⁠וֹ וְ⁠כִתְּתוּ֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠לֹ֥א אַצִּ֖יל מִ⁠יָּדָֽ⁠ם׃","ki̇֠y lò֣ʼ ʼeẖĕm֥wòl ʻ֛wòd ʻal-yòşĕ̌bé֥y há⁠ʼá֖reẕ nĕʼum-yĕhwá֑h wĕ⁠hiné̇֨h ʼánòki֜y mamĕẕi֣yʼ ʼeţ-há⁠ʼádá֗m ʼi֤yş̌ bĕ̇⁠yad-réʻé֨⁠hẇ֙ ẇ⁠bĕ⁠ya֣d malĕk̇֔⁠wò wĕ⁠kiţĕ̇ţẇ֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠lò֥ʼ ʼaẕi֖̇yl mi⁠yá̇dáֽ⁠m׃"],[11,7,"וָֽ⁠אֶרְעֶה֙ אֶת־צֹ֣אן הַֽ⁠הֲרֵגָ֔ה לָ⁠כֵ֖ן עֲנִיֵּ֣י הַ⁠צֹּ֑אן וָ⁠אֶקַּֽח־לִ֞⁠י שְׁנֵ֣י מַקְל֗וֹת לְ⁠אַחַ֞ד קָרָ֤אתִי נֹ֨עַם֙ וּ⁠לְ⁠אַחַד֙ קָרָ֣אתִי חֹֽבְלִ֔ים וָ⁠אֶרְעֶ֖ה אֶת־הַ⁠צֹּֽאן׃","wáֽ⁠ʼerĕʻeh֙ ʼeţ-ẕò֣ʼn haֽ⁠hàrégá֔h lá⁠ké֖n ʻàniyé֣̇y ha⁠ẕò֑̇ʼn wá⁠ʼeqȧֽẖ-li֞⁠y şĕ̌né֣y maqĕl֗wòţ lĕ⁠ʼaẖa֞d qárá֤ʼţiy nò֨ʻam֙ ẇ⁠lĕ⁠ʼaẖad֙ qárá֣ʼţiy ẖòֽbĕli֔ym wá⁠ʼerĕʻe֖h ʼeţ-ha⁠ẕòֽ̇ʼn׃"],[11,8,"וָ⁠אַכְחִ֛ד אֶת־שְׁלֹ֥שֶׁת הָ⁠רֹעִ֖ים בְּ⁠יֶ֣רַח אֶחָ֑ד וַ⁠תִּקְצַ֤ר נַפְשִׁ⁠י֙ בָּ⁠הֶ֔ם וְ⁠גַם־נַפְשָׁ֖⁠ם בָּחֲלָ֥ה בִֽ⁠י׃","wá⁠ʼakĕẖi֛d ʼeţ-şĕ̌lò֥şěţ há⁠ròʻi֖ym bĕ̇⁠ye֣raẖ ʼeẖá֑d wa⁠ţi̇qĕẕa֤r napĕşǐ⁠y֙ bá̇⁠he֔m wĕ⁠gam-napĕşá֖̌⁠m bá̇ẖàlá֥h biֽ⁠y׃"],[11,9,"וָ⁠אֹמַ֕ר לֹ֥א אֶרְעֶ֖ה אֶתְ⁠כֶ֑ם הַ⁠מֵּתָ֣ה תָמ֗וּת וְ⁠הַ⁠נִּכְחֶ֨דֶת֙ תִּכָּחֵ֔ד וְ⁠הַ֨⁠נִּשְׁאָר֔וֹת תֹּאכַ֕לְנָה אִשָּׁ֖ה אֶת־בְּשַׂ֥ר רְעוּתָֽ⁠הּ׃","wá⁠ʼòma֕r lò֥ʼ ʼerĕʻe֖h ʼeţĕ⁠ke֑m ha⁠mé̇ţá֣h ţám֗ẇţ wĕ⁠ha⁠ni̇kĕẖe֨deţ֙ ţi̇ká̇ẖé֔d wĕ⁠ha֨⁠ni̇şĕ̌ʼár֔wòţ ţò̇ʼka֕lĕnáh ʼişá֖̇̌h ʼeţ-bĕ̇şâ֥r rĕʻẇţáֽ⁠ḣ׃"],[11,10,"וָ⁠אֶקַּ֤ח אֶת־מַקְלִ⁠י֙ אֶת־נֹ֔עַם וָ⁠אֶגְדַּ֖ע אֹת֑⁠וֹ לְ⁠הָפֵיר֙ אֶת־בְּרִיתִ֔⁠י אֲשֶׁ֥ר כָּרַ֖תִּי אֶת־כָּל־הָ⁠עַמִּֽים׃","wá⁠ʼeqȧ֤ẖ ʼeţ-maqĕli⁠y֙ ʼeţ-nò֔ʻam wá⁠ʼegĕdȧ֖ʻ ʼòţ֑⁠wò lĕ⁠hápéyr֙ ʼeţ-bĕ̇riyţi֔⁠y ʼàşě֥r ká̇ra֖ţi̇y ʼeţ-ká̇l-há⁠ʻamiֽ̇ym׃"],[11,11,"וַ⁠תֻּפַ֖ר בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠יֵּדְע֨וּ כֵ֜ן עֲנִיֵּ֤י הַ⁠צֹּאן֙ הַ⁠שֹּׁמְרִ֣ים אֹתִ֔⁠י כִּ֥י דְבַר־יְהוָ֖ה הֽוּא׃","wa⁠ţu̇pa֖r bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠yé̇dĕʻ֨ẇ ké֜n ʻàniyé֤̇y ha⁠ẕò̇ʼn֙ ha⁠şò̇̌mĕri֣ym ʼòţi֔⁠y ki֥̇y dĕbar-yĕhwá֖h hֽẇʼ׃"],[11,12,"וָ⁠אֹמַ֣ר אֲלֵי⁠הֶ֗ם אִם־ט֧וֹב בְּ⁠עֵינֵי⁠כֶ֛ם הָב֥וּ שְׂכָרִ֖⁠י וְ⁠אִם־לֹ֣א ׀ חֲדָ֑לוּ וַ⁠יִּשְׁקְל֥וּ אֶת־שְׂכָרִ֖⁠י שְׁלֹשִׁ֥ים כָּֽסֶף׃","wá⁠ʼòma֣r ʼàléy⁠he֗m ʼim-t֧wòb bĕ̇⁠ʻéynéy⁠ke֛m háb֥ẇ şĕ̂kári֖⁠y wĕ⁠ʼim-lò֣ʼ ׀ ẖàdá֑lẇ wa⁠yi̇şĕ̌qĕl֥ẇ ʼeţ-şĕ̂kári֖⁠y şĕ̌lòşǐ֥ym káֽ̇sep׃"],[11,13,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י הַשְׁלִיכֵ֨⁠הוּ֙ אֶל־הַ⁠יּוֹצֵ֔ר אֶ֣דֶר הַ⁠יְקָ֔ר אֲשֶׁ֥ר יָקַ֖רְתִּי מֵֽ⁠עֲלֵי⁠הֶ֑ם וָֽ⁠אֶקְחָ⁠ה֙ שְׁלֹשִׁ֣ים הַ⁠כֶּ֔סֶף וָ⁠אַשְׁלִ֥יךְ אֹת֛⁠וֹ בֵּ֥ית יְהוָ֖ה אֶל־הַ⁠יּוֹצֵֽר׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y haşĕ̌liyké֨⁠hẇ֙ ʼel-ha⁠ẏwòẕé֔r ʼe֣der ha⁠yĕqá֔r ʼàşě֥r yáqa֖rĕţi̇y méֽ⁠ʻàléy⁠he֑m wáֽ⁠ʼeqĕẖá⁠h֙ şĕ̌lòşǐ֣ym ha⁠kė֔sep wá⁠ʼaşĕ̌li֥ykĕ ʼòţ֛⁠wò bé֥̇yţ yĕhwá֖h ʼel-ha⁠ẏwòẕéֽr׃"],[11,14,"וָֽ⁠אֶגְדַּע֙ אֶת־מַקְלִ֣⁠י הַ⁠שֵּׁנִ֔י אֵ֖ת הַ⁠חֹֽבְלִ֑ים לְ⁠הָפֵר֙ אֶת־הָֽ⁠אַחֲוָ֔ה בֵּ֥ין יְהוּדָ֖ה וּ⁠בֵ֥ין יִשְׂרָאֵֽל׃ס","wáֽ⁠ʼegĕdȧʻ֙ ʼeţ-maqĕli֣⁠y ha⁠şé̇̌ni֔y ʼé֖ţ ha⁠ẖòֽbĕli֑ym lĕ⁠hápér֙ ʼeţ-háֽ⁠ʼaẖàwá֔h bé֥̇yn yĕhẇdá֖h ẇ⁠bé֥yn yişĕ̂ráʼéֽl׃s"],[11,15,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י ע֣וֹד קַח־לְ⁠ךָ֔ כְּלִ֖י רֹעֶ֥ה אֱוִלִֽי׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y ʻ֣wòd qaẖ-lĕ⁠ká֔ kĕ̇li֖y ròʻe֥h ʼèwiliֽy׃"],[11,16,"כִּ֣י הִנֵּֽה־אָנֹכִי֩ מֵקִ֨ים רֹעֶ֜ה בָּ⁠אָ֗רֶץ הַ⁠נִּכְחָד֤וֹת לֹֽא־יִפְקֹד֙ הַ⁠נַּ֣עַר לֹֽא־יְבַקֵּ֔שׁ וְ⁠הַ⁠נִּשְׁבֶּ֖רֶת לֹ֣א יְרַפֵּ֑א הַ⁠נִּצָּבָה֙ לֹ֣א יְכַלְכֵּ֔ל וּ⁠בְשַׂ֤ר הַ⁠בְּרִיאָה֙ יֹאכַ֔ל וּ⁠פַרְסֵי⁠הֶ֖ן יְפָרֵֽק׃ס","ki֣̇y hinéֽ̇h-ʼánòkiy֩ méqi֨ym ròʻe֜h bá̇⁠ʼá֗reẕ ha⁠ni̇kĕẖád֤wòţ lòֽʼ-yipĕqòd֙ ha⁠nȧ֣ʻar lòֽʼ-yĕbaqé̇֔ş̌ wĕ⁠ha⁠ni̇şĕ̌bė֖reţ lò֣ʼ yĕrapé֑̇ʼ ha⁠ni̇ẕá̇báh֙ lò֣ʼ yĕkalĕké̇֔l ẇ⁠bĕşâ֤r ha⁠bĕ̇riyʼáh֙ yòʼka֔l ẇ⁠parĕséy⁠he֖n yĕpáréֽq׃s"],[11,17,"ה֣וֹי רֹעִ֤י הָֽ⁠אֱלִיל֙ עֹזְבִ֣י הַ⁠צֹּ֔אן חֶ֥רֶב עַל־זְרוֹע֖⁠וֹ וְ⁠עַל־עֵ֣ין יְמִינ֑⁠וֹ זְרֹע⁠וֹ֙ יָב֣וֹשׁ תִּיבָ֔שׁ וְ⁠עֵ֥ין יְמִינ֖⁠וֹ כָּהֹ֥ה תִכְהֶֽה׃ס","h֣wòy ròʻi֤y háֽ⁠ʼèliyl֙ ʻòzĕbi֣y ha⁠ẕò̇֔ʼn ẖe֥reb ʻal-zĕrwòʻ֖⁠wò wĕ⁠ʻal-ʻé֣yn yĕmiyn֑⁠wò zĕròʻ⁠wò֙ yáb֣wòş̌ ţi̇ybá֔ş̌ wĕ⁠ʻé֥yn yĕmiyn֖⁠wò ká̇hò֥h ţikĕheֽh׃s"],[12,1,"מַשָּׂ֥א דְבַר־יְהוָ֖ה עַל־יִשְׂרָאֵ֑ל נְאֻם־יְהוָ֗ה נֹטֶ֤ה שָׁמַ֨יִם֙ וְ⁠יֹסֵ֣ד אָ֔רֶץ וְ⁠יֹצֵ֥ר רֽוּחַ־אָדָ֖ם בְּ⁠קִרְבּֽ⁠וֹ׃פ","maşá֥̇̂ʼ dĕbar-yĕhwá֖h ʻal-yişĕ̂ráʼé֑l nĕʼum-yĕhwá֗h nòte֤h şá̌ma֨yim֙ wĕ⁠yòsé֣d ʼá֔reẕ wĕ⁠yòẕé֥r rֽẇẖa-ʼádá֖m bĕ̇⁠qirĕḃֽ⁠wò׃p"],[12,2,"הִנֵּ֣ה אָ֠נֹכִי שָׂ֣ם אֶת־יְרוּשָׁלִַ֧ם סַף־רַ֛עַל לְ⁠כָל־הָ⁠עַמִּ֖ים סָבִ֑יב וְ⁠גַ֧ם עַל־יְהוּדָ֛ה יִֽהְיֶ֥ה בַ⁠מָּצ֖וֹר עַל־יְרוּשָׁלִָֽם׃","hiné֣̇h ʼá֠nòkiy şá֣̂m ʼeţ-yĕrẇşá̌lia֧m sap-ra֛ʻal lĕ⁠kál-há⁠ʻami֖̇ym sábi֑yb wĕ⁠ga֧m ʻal-yĕhẇdá֛h yiֽhĕye֥h ba⁠má̇ẕ֖wòr ʻal-yĕrẇşá̌liáֽm׃"],[12,3,"וְ⁠הָיָ֣ה בַ⁠יּוֹם־הַ֠⁠הוּא אָשִׂ֨ים אֶת־יְרוּשָׁלִַ֜ם אֶ֤בֶן מַֽעֲמָסָה֙ לְ⁠כָל־הָ֣⁠עַמִּ֔ים כָּל־עֹמְסֶ֖י⁠הָ שָׂר֣וֹט יִשָּׂרֵ֑טוּ וְ⁠נֶאֶסְפ֣וּ עָלֶ֔י⁠הָ כֹּ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠háyá֣h ba⁠ẏwòm-ha֠⁠hẇʼ ʼáşî֨ym ʼeţ-yĕrẇşá̌lia֜m ʼe֤ben maֽʻàmásáh֙ lĕ⁠kál-há֣⁠ʻami̇֔ym ká̇l-ʻòmĕse֖y⁠há şá̂r֣wòt yişá̇̂ré֑tẇ wĕ⁠neʼesĕp֣ẇ ʻále֔y⁠há kò֖̇l ġwòyé֥y há⁠ʼáֽreẕ׃"],[12,4,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻם־יְהוָ֗ה אַכֶּ֤ה כָל־סוּס֙ בַּ⁠תִּמָּה֔וֹן וְ⁠רֹכְב֖⁠וֹ בַּ⁠שִּׁגָּע֑וֹן וְ⁠עַל־בֵּ֤ית יְהוּדָה֙ אֶפְקַ֣ח אֶת־עֵינַ֔⁠י וְ⁠כֹל֙ ס֣וּס הָֽ⁠עַמִּ֔ים אַכֶּ֖ה בַּֽ⁠עִוָּרֽוֹן׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼum-yĕhwá֗h ʼakė֤h kál-sẇs֙ bȧ⁠ţi̇má̇h֔wòn wĕ⁠ròkĕb֖⁠wò bȧ⁠şi̇̌gá̇ʻ֑wòn wĕ⁠ʻal-bé֤̇yţ yĕhẇdáh֙ ʼepĕqa֣ẖ ʼeţ-ʻéyna֔⁠y wĕ⁠kòl֙ s֣ẇs háֽ⁠ʻami̇֔ym ʼakė֖h bȧֽ⁠ʻiwá̇rֽwòn׃"],[12,5,"וְ⁠אָֽמְר֛וּ אַלֻּפֵ֥י יְהוּדָ֖ה בְּ⁠לִבָּ֑⁠ם אַמְצָ֥ה לִ⁠י֙ יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם בַּ⁠יהוָ֥ה צְבָא֖וֹת אֱלֹהֵי⁠הֶֽם׃","wĕ⁠ʼáֽmĕr֛ẇ ʼalu̇pé֥y yĕhẇdá֖h bĕ̇⁠libá֑̇⁠m ʼamĕẕá֥h li⁠y֙ yòşĕ̌bé֣y yĕrẇşá̌lia֔m bȧ⁠yhwá֥h ẕĕbáʼ֖wòţ ʼèlòhéy⁠heֽm׃"],[12,6,"בַּ⁠יּ֣וֹם הַ⁠ה֡וּא אָשִׂים֩ אֶת־אַלֻּפֵ֨י יְהוּדָ֜ה כְּֽ⁠כִיּ֧וֹר אֵ֣שׁ בְּ⁠עֵצִ֗ים וּ⁠כְ⁠לַפִּ֥יד אֵשׁ֙ בְּ⁠עָמִ֔יר וְ⁠אָ֨כְל֜וּ עַל־יָמִ֧ין וְ⁠עַל־שְׂמֹ֛אול אֶת־כָּל־הָ⁠עַמִּ֖ים סָבִ֑יב וְ⁠יָשְׁבָ֨ה יְרוּשָׁלִַ֥ם ע֛וֹד תַּחְתֶּ֖י⁠הָ בִּ⁠ירוּשָׁלִָֽם׃פ","bȧ⁠ẏ֣wòm ha⁠h֡ẇʼ ʼáşîym֩ ʼeţ-ʼalu̇pé֨y yĕhẇdá֜h kĕֽ̇⁠kiẏ֧wòr ʼé֣ş̌ bĕ̇⁠ʻéẕi֗ym ẇ⁠kĕ⁠lapi֥̇yd ʼéş̌֙ bĕ̇⁠ʻámi֔yr wĕ⁠ʼá֨kĕl֜ẇ ʻal-yámi֧yn wĕ⁠ʻal-şĕ̂mò֛ʼwl ʼeţ-ká̇l-há⁠ʻami֖̇ym sábi֑yb wĕ⁠yáşĕ̌bá֨h yĕrẇşá̌lia֥m ʻ֛wòd ţȧẖĕţė֖y⁠há bi̇⁠yrẇşá̌liáֽm׃p"],[12,7,"וְ⁠הוֹשִׁ֧יעַ יְהוָ֛ה אֶת־אָהֳלֵ֥י יְהוּדָ֖ה בָּ⁠רִֽאשֹׁנָ֑ה לְמַ֨עַן לֹֽא־תִגְדַּ֜ל תִּפְאֶ֣רֶת בֵּית־דָּוִ֗יד וְ⁠תִפְאֶ֛רֶת יֹשֵׁ֥ב יְרוּשָׁלִַ֖ם עַל־יְהוּדָֽה׃","wĕ⁠hwòşǐ֧yʻa yĕhwá֛h ʼeţ-ʼáholé֥y yĕhẇdá֖h bá̇⁠riֽʼşò̌ná֑h lĕma֨ʻan lòֽʼ-ţigĕdȧ֜l ţi̇pĕʼe֣reţ bé̇yţ-dá̇wi֗yd wĕ⁠ţipĕʼe֛reţ yòşé֥̌b yĕrẇşá̌lia֖m ʻal-yĕhẇdáֽh׃"],[12,8,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יָגֵ֤ן יְהוָה֙ בְּעַד֙ יוֹשֵׁ֣ב יְרוּשָׁלִַ֔ם וְ⁠הָיָ֞ה הַ⁠נִּכְשָׁ֥ל בָּ⁠הֶ֛ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כְּ⁠דָוִ֑יד וּ⁠בֵ֤ית דָּוִיד֙ כֵּֽ⁠אלֹהִ֔ים כְּ⁠מַלְאַ֥ךְ יְהוָ֖ה לִ⁠פְנֵי⁠הֶֽם׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yágé֤n yĕhwáh֙ bĕ̇ʻad֙ ywòşé֣̌b yĕrẇşá̌lia֔m wĕ⁠háyá֞h ha⁠ni̇kĕşá֥̌l bá̇⁠he֛m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kĕ̇⁠dáwi֑yd ẇ⁠bé֤yţ dá̇wiyd֙ kéֽ̇⁠ʼlòhi֔ym kĕ̇⁠malĕʼa֥kĕ yĕhwá֖h li⁠pĕnéy⁠heֽm׃"],[12,9,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֲבַקֵּ֗שׁ לְ⁠הַשְׁמִיד֙ אֶת־כָּל־הַ⁠גּוֹיִ֔ם הַ⁠בָּאִ֖ים עַל־יְרוּשָׁלִָֽם׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼàbaqé̇֗ş̌ lĕ⁠haşĕ̌miyd֙ ʼeţ-ká̇l-ha⁠ġwòyi֔m ha⁠bá̇ʼi֖ym ʻal-yĕrẇşá̌liáֽm׃"],[12,10,"וְ⁠שָׁפַכְתִּי֩ עַל־בֵּ֨ית דָּוִ֜יד וְ⁠עַ֣ל ׀ יוֹשֵׁ֣ב יְרוּשָׁלִַ֗ם ר֤וּחַ חֵן֙ וְ⁠תַ֣חֲנוּנִ֔ים וְ⁠הִבִּ֥יטוּ אֵלַ֖⁠י אֵ֣ת אֲשֶׁר־דָּקָ֑רוּ וְ⁠סָפְד֣וּ עָלָ֗י⁠ו כְּ⁠מִסְפֵּד֙ עַל־הַ⁠יָּחִ֔יד וְ⁠הָמֵ֥ר עָלָ֖י⁠ו כְּ⁠הָמֵ֥ר עַֽל־הַ⁠בְּכֽוֹר׃","wĕ⁠şá̌pakĕţi̇y֩ ʻal-bé̇֨yţ dá̇wi֜yd wĕ⁠ʻa֣l ׀ ywòşé֣̌b yĕrẇşá̌lia֗m r֤ẇẖa ẖén֙ wĕ⁠ţa֣ẖànẇni֔ym wĕ⁠hibi֥̇ytẇ ʼéla֖⁠y ʼé֣ţ ʼàşěr-dá̇qá֑rẇ wĕ⁠sápĕd֣ẇ ʻálá֗y⁠w kĕ̇⁠misĕpé̇d֙ ʻal-ha⁠yá̇ẖi֔yd wĕ⁠hámé֥r ʻálá֖y⁠w kĕ̇⁠hámé֥r ʻaֽl-ha⁠bĕ̇kֽwòr׃"],[12,11,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִגְדַּ֤ל הַ⁠מִּסְפֵּד֙ בִּ⁠יר֣וּשָׁלִַ֔ם כְּ⁠מִסְפַּ֥ד הֲדַדְ־רִמּ֖וֹן בְּ⁠בִקְעַ֥ת מְגִדּֽוֹן׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yigĕdȧ֤l ha⁠mi̇sĕpé̇d֙ bi̇⁠yr֣ẇşá̌lia֔m kĕ̇⁠misĕpȧ֥d hàdadĕ-riṁ֖wòn bĕ̇⁠biqĕʻa֥ţ mĕgiḋֽwòn׃"],[12,12,"וְ⁠סָפְדָ֣ה הָ⁠אָ֔רֶץ מִשְׁפָּח֥וֹת מִשְׁפָּח֖וֹת לְ⁠בָ֑ד מִשְׁפַּ֨חַת בֵּית־דָּוִ֤יד לְ⁠בָד֙ וּ⁠נְשֵׁי⁠הֶ֣ם לְ⁠בָ֔ד מִשְׁפַּ֤חַת בֵּית־נָתָן֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃","wĕ⁠sápĕdá֣h há⁠ʼá֔reẕ mişĕ̌pá̇ẖ֥wòţ mişĕ̌pá̇ẖ֖wòţ lĕ⁠bá֑d mişĕ̌pȧ֨ẖaţ bé̇yţ-dá̇wi֤yd lĕ⁠bád֙ ẇ⁠nĕşé̌y⁠he֣m lĕ⁠bá֔d mişĕ̌pȧ֤ẖaţ bé̇yţ-náţán֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃"],[12,13,"מִשְׁפַּ֤חַת בֵּית־לֵוִי֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָ֑ד מִשְׁפַּ֤חַת הַ⁠שִּׁמְעִי֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃","mişĕ̌pȧ֤ẖaţ bé̇yţ-léwiy֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠bá֑d mişĕ̌pȧ֤ẖaţ ha⁠şi̇̌mĕʻiy֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃"],[12,14,"כֹּ֗ל הַ⁠מִּשְׁפָּחוֹת֙ הַ⁠נִּשְׁאָר֔וֹת מִשְׁפָּחֹ֥ת מִשְׁפָּחֹ֖ת לְ⁠בָ֑ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃ס","kò̇֗l ha⁠mi̇şĕ̌pá̇ẖwòţ֙ ha⁠ni̇şĕ̌ʼár֔wòţ mişĕ̌pá̇ẖò֥ţ mişĕ̌pá̇ẖò֖ţ lĕ⁠bá֑d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃s"],[13,1,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ מָק֣וֹר נִפְתָּ֔ח לְ⁠בֵ֥ית דָּוִ֖יד וּ⁠לְ⁠יֹשְׁבֵ֣י יְרֽוּשָׁלִָ֑ם לְ⁠חַטַּ֖את וּ⁠לְ⁠נִדָּֽה׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ máq֣wòr nipĕţá̇֔ẖ lĕ⁠bé֥yţ dá̇wi֖yd ẇ⁠lĕ⁠yòşĕ̌bé֣y yĕrֽẇşá̌liá֑m lĕ⁠ẖatȧ֖ʼţ ẇ⁠lĕ⁠nidáֽ̇h׃"],[13,2,"וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻ֣ם ׀ יְהוָ֣ה צְבָא֗וֹת אַכְרִ֞ית אֶת־שְׁמ֤וֹת הָֽ⁠עֲצַבִּים֙ מִן־הָ⁠אָ֔רֶץ וְ⁠לֹ֥א יִזָּכְר֖וּ ע֑וֹד וְ⁠גַ֧ם אֶת־הַ⁠נְּבִיאִ֛ים וְ⁠אֶת־ר֥וּחַ הַ⁠טֻּמְאָ֖ה אַעֲבִ֥יר מִן־הָ⁠אָֽרֶץ׃","wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼu֣m ׀ yĕhwá֣h ẕĕbáʼ֗wòţ ʼakĕri֞yţ ʼeţ-şĕ̌m֤wòţ háֽ⁠ʻàẕabi̇ym֙ min-há⁠ʼá֔reẕ wĕ⁠lò֥ʼ yizá̇kĕr֖ẇ ʻ֑wòd wĕ⁠ga֧m ʼeţ-ha⁠nĕ̇biyʼi֛ym wĕ⁠ʼeţ-r֥ẇẖa ha⁠tu̇mĕʼá֖h ʼaʻàbi֥yr min-há⁠ʼáֽreẕ׃"],[13,3,"וְ⁠הָיָ֗ה כִּֽי־יִנָּבֵ֣א אִישׁ֮ עוֹד֒ וְ⁠אָמְר֣וּ אֵ֠לָי⁠ו אָבִ֨י⁠ו וְ⁠אִמּ֤⁠וֹ יֹֽלְדָי⁠ו֙ לֹ֣א תִֽחְיֶ֔ה כִּ֛י שֶׁ֥קֶר דִּבַּ֖רְתָּ בְּ⁠שֵׁ֣ם יְהוָ֑ה וּ⁠דְקָרֻ֜⁠הוּ אָבִ֧י⁠הוּ וְ⁠אִמּ֛⁠וֹ יֹלְדָ֖י⁠ו בְּ⁠הִנָּבְאֽ⁠וֹ׃","wĕ⁠háyá֗h kiֽ̇y-yiná̇bé֣ʼ ʼiyş֮̌ ʻwòd֒ wĕ⁠ʼámĕr֣ẇ ʼé֠láy⁠w ʼábi֨y⁠w wĕ⁠ʼiṁ֤⁠wò yòֽlĕdáy⁠w֙ lò֣ʼ ţiֽẖĕye֔h ki֛̇y şě֥qer di̇bȧ֖rĕţá̇ bĕ̇⁠şé֣̌m yĕhwá֑h ẇ⁠dĕqáru֜⁠hẇ ʼábi֧y⁠hẇ wĕ⁠ʼiṁ֛⁠wò yòlĕdá֖y⁠w bĕ̇⁠hiná̇bĕʼֽ⁠wò׃"],[13,4,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יֵבֹ֧שׁוּ הַ⁠נְּבִיאִ֛ים אִ֥ישׁ מֵ⁠חֶזְיֹנ֖⁠וֹ בְּ⁠הִנָּֽבְאֹת֑⁠וֹ וְ⁠לֹ֧א יִלְבְּשׁ֛וּ אַדֶּ֥רֶת שֵׂעָ֖ר לְמַ֥עַן כַּחֵֽשׁ׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yébò֧ş̌ẇ ha⁠nĕ̇biyʼi֛ym ʼi֥yş̌ mé⁠ẖezĕyòn֖⁠wò bĕ̇⁠hináֽ̇bĕʼòţ֑⁠wò wĕ⁠lò֧ʼ yilĕbĕ̇ş֛̌ẇ ʼadė֥reţ şé̂ʻá֖r lĕma֥ʻan kȧẖéֽş̌׃"],[13,5,"וְ⁠אָמַ֕ר לֹ֥א נָבִ֖יא אָנֹ֑כִי אִישׁ־עֹבֵ֤ד אֲדָמָה֙ אָנֹ֔כִי כִּ֥י אָדָ֖ם הִקְנַ֥⁠נִי מִ⁠נְּעוּרָֽ⁠י׃","wĕ⁠ʼáma֕r lò֥ʼ nábi֖yʼ ʼánò֑kiy ʼiyş̌-ʻòbé֤d ʼàdámáh֙ ʼánò֔kiy ki֥̇y ʼádá֖m hiqĕna֥⁠niy mi⁠nĕ̇ʻẇráֽ⁠y׃"],[13,6,"וְ⁠אָמַ֣ר אֵלָ֔י⁠ו מָ֧ה הַ⁠מַּכּ֛וֹת הָ⁠אֵ֖לֶּה בֵּ֣ין יָדֶ֑י⁠ךָ וְ⁠אָמַ֕ר אֲשֶׁ֥ר הֻכֵּ֖יתִי בֵּ֥ית מְאַהֲבָֽ⁠י׃ס","wĕ⁠ʼáma֣r ʼélá֔y⁠w má֧h ha⁠mȧk֛̇wòţ há⁠ʼé֖lėh bé֣̇yn yáde֑y⁠ká wĕ⁠ʼáma֕r ʼàşě֥r huké֖̇yţiy bé֥̇yţ mĕʼahàbáֽ⁠y׃s"],[13,7,"חֶ֗רֶב עוּרִ֤י עַל־רֹעִ⁠י֙ וְ⁠עַל־גֶּ֣בֶר עֲמִיתִ֔⁠י נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת הַ֤ךְ אֶת־הָֽ⁠רֹעֶה֙ וּ⁠תְפוּצֶ֣יןָ הַ⁠צֹּ֔אן וַ⁠הֲשִׁבֹתִ֥י יָדִ֖⁠י עַל־הַ⁠צֹּעֲרִֽים׃","ẖe֗reb ʻẇri֤y ʻal-ròʻi⁠y֙ wĕ⁠ʻal-gė֣ber ʻàmiyţi֔⁠y nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ ha֤kĕ ʼeţ-háֽ⁠ròʻeh֙ ẇ⁠ţĕpẇẕe֣yná ha⁠ẕò̇֔ʼn wa⁠hàşǐbòţi֥y yádi֖⁠y ʻal-ha⁠ẕò̇ʻàriֽym׃"],[13,8,"וְ⁠הָיָ֤ה בְ⁠כָל־הָ⁠אָ֨רֶץ֙ נְאֻם־יְהוָ֔ה פִּֽי־שְׁנַ֣יִם בָּ֔⁠הּ יִכָּרְת֖וּ יִגְוָ֑עוּ וְ⁠הַ⁠שְּׁלִשִׁ֖ית יִוָּ֥תֶר בָּֽ⁠הּ׃","wĕ⁠háyá֤h bĕ⁠kál-há⁠ʼá֨reẕ֙ nĕʼum-yĕhwá֔h piֽ̇y-şĕ̌na֣yim bá̇֔⁠ḣ yiká̇rĕţ֖ẇ yigĕwá֑ʻẇ wĕ⁠ha⁠şĕ̇̌lişǐ֖yţ yiwá֥̇ţer báֽ̇⁠ḣ׃"],[13,9,"וְ⁠הֵבֵאתִ֤י אֶת־הַ⁠שְּׁלִשִׁית֙ בָּ⁠אֵ֔שׁ וּ⁠צְרַפְתִּי⁠ם֙ כִּ⁠צְרֹ֣ף אֶת־הַ⁠כֶּ֔סֶף וּ⁠בְחַנְתִּ֖י⁠ם כִּ⁠בְחֹ֣ן אֶת־הַ⁠זָּהָ֑ב ה֣וּא ׀ יִקְרָ֣א בִ⁠שְׁמִ֗⁠י וַֽ⁠אֲנִי֙ אֶעֱנֶ֣ה אֹת֔⁠וֹ אָמַ֨רְתִּי֙ עַמִּ֣⁠י ה֔וּא וְ⁠ה֥וּא יֹאמַ֖ר יְהוָ֥ה אֱלֹהָֽ⁠י׃ס","wĕ⁠hébéʼţi֤y ʼeţ-ha⁠şĕ̇̌lişǐyţ֙ bá̇⁠ʼé֔ş̌ ẇ⁠ẕĕrapĕţi̇y⁠m֙ ki̇⁠ẕĕrò֣p ʼeţ-ha⁠kė֔sep ẇ⁠bĕẖanĕţi֖̇y⁠m ki̇⁠bĕẖò֣n ʼeţ-ha⁠zá̇há֑b h֣ẇʼ ׀ yiqĕrá֣ʼ bi⁠şĕ̌mi֗⁠y waֽ⁠ʼàniy֙ ʼeʻène֣h ʼòţ֔⁠wò ʼáma֨rĕţi̇y֙ ʻami֣̇⁠y h֔ẇʼ wĕ⁠h֥ẇʼ yòʼma֖r yĕhwá֥h ʼèlòháֽ⁠y׃s"],[14,1,"הִנֵּ֥ה יֽוֹם־בָּ֖א לַֽ⁠יהוָ֑ה וְ⁠חֻלַּ֥ק שְׁלָלֵ֖⁠ךְ בְּ⁠קִרְבֵּֽ⁠ךְ׃","hiné֥̇h yֽwòm-bá֖̇ʼ laֽ⁠yhwá֑h wĕ⁠ẖulȧ֥q şĕ̌lálé֖⁠kĕ bĕ̇⁠qirĕbéֽ̇⁠kĕ׃"],[14,2,"וְ⁠אָסַפְתִּ֨י אֶת־כָּל־הַ⁠גּוֹיִ֥ם ׀ אֶֽל־יְרוּשָׁלִַם֮ לַ⁠מִּלְחָמָה֒ וְ⁠נִלְכְּדָ֣ה הָ⁠עִ֗יר וְ⁠נָשַׁ֨סּוּ֙ הַ⁠בָּ֣תִּ֔ים וְ⁠הַ⁠נָּשִׁ֖ים תשגלנה וְ⁠יָצָ֞א חֲצִ֤י הָ⁠עִיר֙ בַּ⁠גּוֹלָ֔ה וְ⁠יֶ֣תֶר הָ⁠עָ֔ם לֹ֥א יִכָּרֵ֖ת מִן־הָ⁠עִֽיר׃","wĕ⁠ʼásapĕţi̇֨y ʼeţ-ká̇l-ha⁠ġwòyi֥m ׀ ʼeֽl-yĕrẇşá̌liam֮ la⁠mi̇lĕẖámáh֒ wĕ⁠nilĕkĕ̇dá֣h há⁠ʻi֗yr wĕ⁠náşǎ֨ṡẇ֙ ha⁠bá֣̇ţi̇֔ym wĕ⁠ha⁠ná̇şǐ֖ym ţşglnh wĕ⁠yáẕá֞ʼ ẖàẕi֤y há⁠ʻiyr֙ bȧ⁠ġwòlá֔h wĕ⁠ye֣ţer há⁠ʻá֔m lò֥ʼ yiká̇ré֖ţ min-há⁠ʻiֽyr׃"],[14,3,"וְ⁠יָצָ֣א יְהוָ֔ה וְ⁠נִלְחַ֖ם בַּ⁠גּוֹיִ֣ם הָ⁠הֵ֑ם כְּ⁠י֥וֹם הִֽלָּחֲמ֖⁠ו בְּ⁠י֥וֹם קְרָֽב׃","wĕ⁠yáẕá֣ʼ yĕhwá֔h wĕ⁠nilĕẖa֖m bȧ⁠ġwòyi֣m há⁠hé֑m kĕ̇⁠y֥wòm hiֽlá̇ẖàm֖⁠w bĕ̇⁠y֥wòm qĕráֽb׃"],[14,4,"וְ⁠עָמְד֣וּ רַגְלָ֣י⁠ו בַּ⁠יּוֹם־הַ֠⁠הוּא עַל־הַ֨ר הַ⁠זֵּתִ֜ים אֲשֶׁ֨ר עַל־פְּנֵ֥י יְרוּשָׁלִַם֮ מִ⁠קֶּדֶם֒ וְ⁠נִבְקַע֩ הַ֨ר הַ⁠זֵּיתִ֤ים מֵֽ⁠חֶצְי⁠וֹ֙ מִזְרָ֣חָ⁠ה וָ⁠יָ֔מָּ⁠ה גֵּ֖יא גְּדוֹלָ֣ה מְאֹ֑ד וּ⁠מָ֨שׁ חֲצִ֥י הָ⁠הָ֛ר צָפ֖וֹנָ⁠ה וְ⁠חֶצְי⁠וֹ־נֶֽגְבָּ⁠ה׃","wĕ⁠ʻámĕd֣ẇ ragĕlá֣y⁠w bȧ⁠ẏwòm-ha֠⁠hẇʼ ʻal-ha֨r ha⁠zé̇ţi֜ym ʼàşě֨r ʻal-pĕ̇né֥y yĕrẇşá̌liam֮ mi⁠qėdem֒ wĕ⁠nibĕqaʻ֩ ha֨r ha⁠zé̇yţi֤ym méֽ⁠ẖeẕĕy⁠wò֙ mizĕrá֣ẖá⁠h wá⁠yá֔má̇⁠h gé֖̇yʼ gĕ̇dwòlá֣h mĕʼò֑d ẇ⁠má֨ş̌ ẖàẕi֥y há⁠há֛r ẕáp֖wòná⁠h wĕ⁠ẖeẕĕy⁠wò-neֽgĕbá̇⁠h׃"],[14,5,"וְ⁠נַסְתֶּ֣ם גֵּֽיא־הָרַ֗⁠י כִּֽי־יַגִּ֣יעַ גֵּי־הָרִים֮ אֶל־אָצַל֒ וְ⁠נַסְתֶּ֗ם כַּ⁠אֲשֶׁ֤ר נַסְתֶּם֙ מִ⁠פְּנֵ֣י הָ⁠רַ֔עַשׁ בִּ⁠ימֵ֖י עֻזִּיָּ֣ה מֶֽלֶךְ־יְהוּדָ֑ה וּ⁠בָא֙ יְהוָ֣ה אֱלֹהַ֔⁠י כָּל־קְדֹשִׁ֖ים עִמָּֽ⁠ךְ׃","wĕ⁠nasĕţė֣m géֽ̇yʼ-hára֗⁠y kiֽ̇y-yagi֣̇yʻa gé̇y-háriym֮ ʼel-ʼáẕal֒ wĕ⁠nasĕţė֗m kȧ⁠ʼàşě֤r nasĕţėm֙ mi⁠pĕ̇né֣y há⁠ra֔ʻaş̌ bi̇⁠ymé֖y ʻuzi̇yá֣̇h meֽlekĕ-yĕhẇdá֑h ẇ⁠báʼ֙ yĕhwá֣h ʼèlòha֔⁠y ká̇l-qĕdòşǐ֖ym ʻimáֽ̇⁠kĕ׃"],[14,6,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא לֹֽא־יִהְיֶ֣ה א֔וֹר יְקָר֖וֹת יקפאו⁠ן׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ lòֽʼ-yihĕye֣h ʼ֔wòr yĕqár֖wòţ yqpʼw⁠n׃"],[14,7,"וְ⁠הָיָ֣ה יוֹם־אֶחָ֗ד ה֛וּא יִוָּדַ֥ע לַֽ⁠יהוָ֖ה לֹא־י֣וֹם וְ⁠לֹא־לָ֑יְלָה וְ⁠הָיָ֥ה לְ⁠עֵֽת־עֶ֖רֶב יִֽהְיֶה־אֽוֹר׃","wĕ⁠háyá֣h ywòm-ʼeẖá֗d h֛ẇʼ yiwá̇da֥ʻ laֽ⁠yhwá֖h lòʼ-y֣wòm wĕ⁠lòʼ-lá֑yĕláh wĕ⁠háyá֥h lĕ⁠ʻéֽţ-ʻe֖reb yiֽhĕyeh-ʼֽwòr׃"],[14,8,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יֵצְא֤וּ מַֽיִם־חַיִּים֙ מִ⁠יר֣וּשָׁלִַ֔ם חֶצְיָ֗⁠ם אֶל־הַ⁠יָּם֙ הַ⁠קַּדְמוֹנִ֔י וְ⁠חֶצְיָ֖⁠ם אֶל־הַ⁠יָּ֣ם הָ⁠אַחֲר֑וֹן בַּ⁠קַּ֥יִץ וּ⁠בָ⁠חֹ֖רֶף יִֽהְיֶֽה׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yéẕĕʼ֤ẇ maֽyim-ẖayi̇ym֙ mi⁠yr֣ẇşá̌lia֔m ẖeẕĕyá֗⁠m ʼel-ha⁠yá̇m֙ ha⁠qȧdĕmwòni֔y wĕ⁠ẖeẕĕyá֖⁠m ʼel-ha⁠yá֣̇m há⁠ʼaẖàr֑wòn bȧ⁠qȧ֥yiẕ ẇ⁠bá⁠ẖò֖rep yiֽhĕyeֽh׃"],[14,9,"וְ⁠הָיָ֧ה יְהוָ֛ה לְ⁠מֶ֖לֶךְ עַל־כָּל־הָ⁠אָ֑רֶץ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִהְיֶ֧ה יְהוָ֛ה אֶחָ֖ד וּ⁠שְׁמ֥⁠וֹ אֶחָֽד׃","wĕ⁠háyá֧h yĕhwá֛h lĕ⁠me֖lekĕ ʻal-ká̇l-há⁠ʼá֑reẕ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yihĕye֧h yĕhwá֛h ʼeẖá֖d ẇ⁠şĕ̌m֥⁠wò ʼeẖáֽd׃"],[14,10,"יִסּ֨וֹב כָּל־הָ⁠אָ֤רֶץ כָּ⁠עֲרָבָה֙ מִ⁠גֶּ֣בַע לְ⁠רִמּ֔וֹן נֶ֖גֶב יְרֽוּשָׁלִָ֑ם וְֽ⁠רָאֲמָה֩ וְ⁠יָשְׁבָ֨ה תַחְתֶּ֜י⁠הָ לְ⁠מִ⁠שַּׁ֣עַר בִּנְיָמִ֗ן עַד־מְק֞וֹם שַׁ֤עַר הָֽ⁠רִאשׁוֹן֙ עַד־שַׁ֣עַר הַ⁠פִּנִּ֔ים וּ⁠מִגְדַּ֣ל חֲנַנְאֵ֔ל עַ֖ד יִקְבֵ֥י הַ⁠מֶּֽלֶךְ׃","yiṡ֨wòb ká̇l-há⁠ʼá֤reẕ ká̇⁠ʻàrábáh֙ mi⁠gė֣baʻ lĕ⁠riṁ֔wòn ne֖geb yĕrֽẇşá̌liá֑m wĕֽ⁠ráʼàmáh֩ wĕ⁠yáşĕ̌bá֨h ţaẖĕţė֜y⁠há lĕ⁠mi⁠şȧ֣̌ʻar bi̇nĕyámi֗n ʻad-mĕq֞wòm şǎ֤ʻar háֽ⁠riʼş̌wòn֙ ʻad-şǎ֣ʻar ha⁠pi̇ni̇֔ym ẇ⁠migĕdȧ֣l ẖànanĕʼé֔l ʻa֖d yiqĕbé֥y ha⁠mėֽlekĕ׃"],[14,11,"וְ⁠יָ֣שְׁבוּ בָ֔⁠הּ וְ⁠חֵ֖רֶם לֹ֣א יִֽהְיֶה־ע֑וֹד וְ⁠יָשְׁבָ֥ה יְרוּשָׁלִַ֖ם לָ⁠בֶֽטַח׃","wĕ⁠yá֣şĕ̌bẇ bá֔⁠ḣ wĕ⁠ẖé֖rem lò֣ʼ yiֽhĕyeh-ʻ֑wòd wĕ⁠yáşĕ̌bá֥h yĕrẇşá̌lia֖m lá⁠beֽtaẖ׃"],[14,12,"וְ⁠זֹ֣את ׀ תִּֽהְיֶ֣ה הַ⁠מַּגֵּפָ֗ה אֲשֶׁ֨ר יִגֹּ֤ף יְהוָה֙ אֶת־כָּל־הָ֣⁠עַמִּ֔ים אֲשֶׁ֥ר צָבְא֖וּ עַל־יְרוּשָׁלִָ֑ם הָמֵ֣ק ׀ בְּשָׂר֗⁠וֹ וְ⁠הוּא֙ עֹמֵ֣ד עַל־רַגְלָ֔י⁠ו וְ⁠עֵינָי⁠ו֙ תִּמַּ֣קְנָה בְ⁠חֹֽרֵי⁠הֶ֔ן וּ⁠לְשׁוֹנ֖⁠וֹ תִּמַּ֥ק בְּ⁠פִי⁠הֶֽם׃","wĕ⁠zò֣ʼţ ׀ ţiֽ̇hĕye֣h ha⁠mȧgé̇pá֗h ʼàşě֨r yigò֤̇p yĕhwáh֙ ʼeţ-ká̇l-há֣⁠ʻami̇֔ym ʼàşě֥r ẕábĕʼ֖ẇ ʻal-yĕrẇşá̌liá֑m hámé֣q ׀ bĕ̇şá̂r֗⁠wò wĕ⁠hẇʼ֙ ʻòmé֣d ʻal-ragĕlá֔y⁠w wĕ⁠ʻéynáy⁠w֙ ţi̇mȧ֣qĕnáh bĕ⁠ẖòֽréy⁠he֔n ẇ⁠lĕş̌wòn֖⁠wò ţi̇mȧ֥q bĕ̇⁠piy⁠heֽm׃"],[14,13,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא תִּֽהְיֶ֧ה מְהֽוּמַת־יְהוָ֛ה רַבָּ֖ה בָּ⁠הֶ֑ם וְ⁠הֶחֱזִ֗יקוּ אִ֚ישׁ יַ֣ד רֵעֵ֔⁠הוּ וְ⁠עָלְתָ֥ה יָד֖⁠וֹ עַל־יַ֥ד רֵעֵֽ⁠הוּ׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ţiֽ̇hĕye֧h mĕhֽẇmaţ-yĕhwá֛h rabá֖̇h bá̇⁠he֑m wĕ⁠heẖèzi֗yqẇ ʼi֚yş̌ ya֣d réʻé֔⁠hẇ wĕ⁠ʻálĕţá֥h yád֖⁠wò ʻal-ya֥d réʻéֽ⁠hẇ׃"],[14,14,"וְ⁠גַ֨ם־יְהוּדָ֔ה תִּלָּחֵ֖ם בִּ⁠ירֽוּשָׁלִָ֑ם וְ⁠אֻסַּף֩ חֵ֨יל כָּל־הַ⁠גּוֹיִ֜ם סָבִ֗יב זָהָ֥ב וָ⁠כֶ֛סֶף וּ⁠בְגָדִ֖ים לָ⁠רֹ֥ב מְאֹֽד׃","wĕ⁠ga֨m-yĕhẇdá֔h ţi̇lá̇ẖé֖m bi̇⁠yrֽẇşá̌liá֑m wĕ⁠ʼusȧp֩ ẖé֨yl ká̇l-ha⁠ġwòyi֜m sábi֗yb záhá֥b wá⁠ke֛sep ẇ⁠bĕgádi֖ym lá⁠rò֥b mĕʼòֽd׃"],[14,15,"וְ⁠כֵ֨ן תִּֽהְיֶ֜ה מַגֵּפַ֣ת הַ⁠סּ֗וּס הַ⁠פֶּ֨רֶד֙ הַ⁠גָּמָ֣ל וְ⁠הַ⁠חֲמ֔וֹר וְ⁠כָ֨ל־הַ⁠בְּהֵמָ֔ה אֲשֶׁ֥ר יִהְיֶ֖ה בַּ⁠מַּחֲנ֣וֹת הָ⁠הֵ֑מָּה כַּ⁠מַּגֵּפָ֖ה הַ⁠זֹּֽאת׃","wĕ⁠ké֨n ţiֽ̇hĕye֜h magé̇pa֣ţ ha⁠ṡ֗ẇs ha⁠pė֨red֙ ha⁠gá̇má֣l wĕ⁠ha⁠ẖàm֔wòr wĕ⁠ká֨l-ha⁠bĕ̇hémá֔h ʼàşě֥r yihĕye֖h bȧ⁠mȧẖàn֣wòţ há⁠hé֑má̇h kȧ⁠mȧgé̇pá֖h ha⁠zòֽ̇ʼţ׃"],[14,16,"וְ⁠הָיָ֗ה כָּל־הַ⁠נּוֹתָר֙ מִ⁠כָּל־הַ⁠גּוֹיִ֔ם הַ⁠בָּאִ֖ים עַל־יְרֽוּשָׁלִָ֑ם וְ⁠עָל֞וּ מִ⁠דֵּ֧י שָׁנָ֣ה בְ⁠שָׁנָ֗ה לְ⁠הִֽשְׁתַּחֲוֺת֙ לְ⁠מֶ֨לֶךְ֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","wĕ⁠háyá֗h ká̇l-ha⁠ṅwòţár֙ mi⁠ká̇l-ha⁠ġwòyi֔m ha⁠bá̇ʼi֖ym ʻal-yĕrֽẇşá̌liá֑m wĕ⁠ʻál֞ẇ mi⁠dé֧̇y şá̌ná֣h bĕ⁠şá̌ná֗h lĕ⁠hiֽşĕ̌ţȧẖàwֺţ֙ lĕ⁠me֨lekĕ֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,17,"וְ֠⁠הָיָה אֲשֶׁ֨ר לֹֽא־יַעֲלֶ֜ה מֵ⁠אֵ֨ת מִשְׁפְּח֤וֹת הָ⁠אָ֨רֶץ֙ אֶל־יְר֣וּשָׁלִַ֔ם לְ⁠הִֽשְׁתַּחֲוֺ֔ת לְ⁠מֶ֖לֶךְ יְהוָ֣ה צְבָא֑וֹת וְ⁠לֹ֥א עֲלֵי⁠הֶ֖ם יִהְיֶ֥ה הַ⁠גָּֽשֶׁם׃","wĕ֠⁠háyáh ʼàşě֨r lòֽʼ-yaʻàle֜h mé⁠ʼé֨ţ mişĕ̌pĕ̇ẖ֤wòţ há⁠ʼá֨reẕ֙ ʼel-yĕr֣ẇşá̌lia֔m lĕ⁠hiֽşĕ̌ţȧẖàwֺ֔ţ lĕ⁠me֖lekĕ yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠lò֥ʼ ʻàléy⁠he֖m yihĕye֥h ha⁠gáֽ̇şěm׃"],[14,18,"וְ⁠אִם־מִשְׁפַּ֨חַת מִצְרַ֧יִם לֹֽא־תַעֲלֶ֛ה וְ⁠לֹ֥א בָאָ֖ה וְ⁠לֹ֣א עֲלֵי⁠הֶ֑ם תִּֽהְיֶ֣ה הַ⁠מַּגֵּפָ֗ה אֲשֶׁ֨ר יִגֹּ֤ף יְהוָה֙ אֶת־הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ לֹ֣א יַֽעֲל֔וּ לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","wĕ⁠ʼim-mişĕ̌pȧ֨ẖaţ miẕĕra֧yim lòֽʼ-ţaʻàle֛h wĕ⁠lò֥ʼ báʼá֖h wĕ⁠lò֣ʼ ʻàléy⁠he֑m ţiֽ̇hĕye֣h ha⁠mȧgé̇pá֗h ʼàşě֨r yigò֤̇p yĕhwáh֙ ʼeţ-ha⁠ġwòyi֔m ʼàşěr֙ lò֣ʼ yaֽʻàl֔ẇ lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,19,"זֹ֥את תִּהְיֶ֖ה חַטַּ֣את מִצְרָ֑יִם וְ⁠חַטַּאת֙ כָּל־הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ לֹ֣א יַֽעֲל֔וּ לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","zò֥ʼţ ţi̇hĕye֖h ẖatȧ֣ʼţ miẕĕrá֑yim wĕ⁠ẖatȧʼţ֙ ká̇l-ha⁠ġwòyi֔m ʼàşěr֙ lò֣ʼ yaֽʻàl֔ẇ lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,20,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ עַל־מְצִלּ֣וֹת הַ⁠סּ֔וּס קֹ֖דֶשׁ לַֽ⁠יהוָ֑ה וְ⁠הָיָ֤ה הַ⁠סִּירוֹת֙ בְּ⁠בֵ֣ית יְהוָ֔ה כַּ⁠מִּזְרָקִ֖ים לִ⁠פְנֵ֥י הַ⁠מִּזְבֵּֽחַ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ ʻal-mĕẕil֣̇wòţ ha⁠ṡ֔ẇs qò֖deş̌ laֽ⁠yhwá֑h wĕ⁠háyá֤h ha⁠si̇yrwòţ֙ bĕ̇⁠bé֣yţ yĕhwá֔h kȧ⁠mi̇zĕráqi֖ym li⁠pĕné֥y ha⁠mi̇zĕbéֽ̇ẖa׃"],[14,21,"וְ֠⁠הָיָה כָּל־סִ֨יר בִּ⁠ירוּשָׁלִַ֜ם וּ⁠בִֽ⁠יהוּדָ֗ה קֹ֚דֶשׁ לַ⁠יהוָ֣ה צְבָא֔וֹת וּ⁠בָ֨אוּ֙ כָּל־הַ⁠זֹּ֣בְחִ֔ים וְ⁠לָקְח֥וּ מֵ⁠הֶ֖ם וּ⁠בִשְּׁל֣וּ בָ⁠הֶ֑ם וְ⁠לֹא־יִהְיֶ֨ה כְנַעֲנִ֥י ע֛וֹד בְּ⁠בֵית־יְהוָ֥ה צְבָא֖וֹת בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","wĕ֠⁠háyáh ká̇l-si֨yr bi̇⁠yrẇşá̌lia֜m ẇ⁠biֽ⁠yhẇdá֗h qò֚deş̌ la⁠yhwá֣h ẕĕbáʼ֔wòţ ẇ⁠bá֨ʼẇ֙ ká̇l-ha⁠zò֣̇bĕẖi֔ym wĕ⁠láqĕẖ֥ẇ mé⁠he֖m ẇ⁠bişĕ̇̌l֣ẇ bá⁠he֑m wĕ⁠lòʼ-yihĕye֨h kĕnaʻàni֥y ʻ֛wòd bĕ̇⁠béyţ-yĕhwá֥h ẕĕbáʼ֖wòţ bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"]]}};